  :root{
    --bg-deep:#050914;
    --bg-navy:#0a1330;
    --panel:#0e1a3aee;
    --panel-line:#1e3a6d;
    --blue:#3fa9ff;
    --blue-glow:#5ec2ff;
    --red:#ff4d6a;
    --red-glow:#ff7d92;
    --gold:#ffce54;
    --green:#37e39a;
    --purple:#b06bff;
    --text:#eaf2ff;
    --dim:#7d93bf;
  }
  *{box-sizing:border-box; -webkit-tap-highlight-color:transparent; user-select:none; -webkit-user-select:none;}
  html,body{
    margin:0; padding:0; width:100%; height:100%; overflow:hidden;
    background:var(--bg-deep);
    font-family:'Segoe UI', system-ui, -apple-system, Roboto, sans-serif;
    color:var(--text);
    overscroll-behavior:none;
    touch-action:none;
  }
  #app{position:fixed; inset:0; overflow:hidden;}
  @media (min-width:600px){
    html,body{ background:#000; }
    #app{
      position:fixed; top:0; bottom:0; left:50%; transform:translateX(-50%);
      width:480px; max-width:100vw; overflow:hidden;
      box-shadow:0 0 60px #000000cc, 0 0 0 1px var(--panel-line);
    }
  }
  .screen{
    position:absolute; inset:0; display:none; flex-direction:column;
    background:
      radial-gradient(1.5px 1.5px at 14% 20%, #3fa9ff26, transparent 60%),
      radial-gradient(1.5px 1.5px at 78% 14%, #5ec2ff20, transparent 60%),
      radial-gradient(1.5px 1.5px at 55% 62%, #3fa9ff1c, transparent 60%),
      radial-gradient(1.5px 1.5px at 30% 78%, #5ec2ff1a, transparent 60%),
      radial-gradient(1.5px 1.5px at 90% 72%, #3fa9ff18, transparent 60%),
      radial-gradient(1.5px 1.5px at 8% 55%, #5ec2ff16, transparent 60%),
      linear-gradient(#3fa9ff14 1px, transparent 1px),
      linear-gradient(90deg, #3fa9ff14 1px, transparent 1px),
      radial-gradient(900px 600px at 50% -10%, #101c3f2e, transparent 62%),
      radial-gradient(1100px 700px at 50% 55%, #10254d33, transparent 70%),
      linear-gradient(180deg, #060c1c 0%, #030509 100%);
    background-size:auto,auto,auto,auto,auto,auto,40px 40px,40px 40px,auto,auto,auto;
  }
  .screen.active{display:flex;}
  .scroll{overflow-y:auto; -webkit-overflow-scrolling:touch; touch-action:pan-y;}

  /* ---------- Shared UI ---------- */
  .brand{
    font-weight:900; letter-spacing:2px; font-size:2.6em;
    background:linear-gradient(90deg, var(--blue-glow), var(--red-glow));
    -webkit-background-clip:text; background-clip:text; color:transparent;
    text-shadow:0 0 30px #3fa9ff55;
    text-align:center; margin:0;
  }
  .tagline{text-align:center; color:var(--dim); font-size:.8em; letter-spacing:3px; margin-top:2px;}

  .glass{
    background:var(--panel);
    border:1px solid var(--panel-line);
    border-radius:18px;
    backdrop-filter:blur(10px);
    box-shadow:0 8px 32px #00000066, inset 0 1px 0 #ffffff0f;
  }

  .btn{
    display:flex; align-items:center; justify-content:center; gap:10px;
    padding:16px 20px; border-radius:16px; border:1px solid #ffffff1a;
    font-size:1.05em; font-weight:700; letter-spacing:.5px; color:var(--text);
    background:linear-gradient(180deg,#182a5c,#0f1c40);
    box-shadow:0 6px 18px #00000055, inset 0 1px 0 #ffffff14;
    cursor:pointer; transition:transform .08s ease, box-shadow .08s ease;
  }
  .btn:active{transform:scale(.96); box-shadow:0 2px 8px #00000055;}
  .btn.primary{
    background:linear-gradient(135deg, var(--blue), #1f6fe0);
    box-shadow:0 8px 24px #3fa9ff55, inset 0 1px 0 #ffffff33;
    border-color:#5ec2ff55;
  }
  .btn.ghost{
    background:linear-gradient(180deg,#0d1a3a99,#0a132666);
    border:1px solid #22335f;
    backdrop-filter:blur(8px);
    box-shadow:0 2px 8px #00000040;
    color:var(--blue-glow);
  }
  .btn.ghost:active{border-color:#2f4a80; box-shadow:0 1px 4px #00000040;}
  .btn.gold{
    background:linear-gradient(135deg, var(--gold), #e0a92e);
    box-shadow:0 6px 16px #ffce5444, inset 0 1px 0 #ffffff33;
    border-color:#ffce5455;
    color:#1a1206;
  }
  .btn.gold:active{box-shadow:0 2px 8px #ffce5433;}
  .btn.small{padding:10px 14px; font-size:.85em; border-radius:12px;}
  .btn:disabled{opacity:.4; pointer-events:none;}
  .btn.disabled{opacity:.4; pointer-events:none;}

  /* Navigation/action buttons (Shop, Ranks, Leaderboard, Settings, Main Menu row, etc.) —
     dark premium glass chrome: understated body, thin border, soft shadow, only a faint
     hint of blue accent (not a glowing neon frame). */
  .btn.glass{
    background:linear-gradient(180deg,#101f45,#0a1330);
    border:1px solid #22335f;
    backdrop-filter:blur(10px);
    box-shadow:0 4px 14px #00000045, inset 0 1px 0 #ffffff0d;
    transition:transform .08s ease, box-shadow .15s ease, border-color .15s ease;
  }
  .btn.glass:active{
    border-color:#2f4a80;
    box-shadow:0 2px 6px #00000045, inset 0 1px 0 #ffffff0a;
  }
  @media (hover:hover){
    .btn.glass:hover{border-color:#2c4676;}
  }

  /* Back buttons — minimal, premium, dark glass pill: small arrow + "BACK" label,
     thin subtle border, very slight shadow, no neon glow. */
  .icon-btn.back-btn{
    width:auto; min-width:44px; height:44px; padding:0 16px 0 14px; border-radius:14px;
    gap:6px;
  }
  .icon-btn.back-btn::after{content:'BACK'; font-size:.72em; font-weight:800; letter-spacing:.6px; color:var(--dim);}
  .icon-btn.back-btn:active::after{color:var(--text);}

  /* Generic icon-style buttons (pause, cancel, exit) — same dark glass language,
     kept icon-only since their action isn't literally "back". */
  .icon-btn{
    width:44px; height:44px; min-width:44px; min-height:44px; border-radius:14px;
    display:flex; align-items:center; justify-content:center;
    background:linear-gradient(180deg,#101f45,#0a1330);
    border:1px solid #22335f;
    backdrop-filter:blur(10px);
    box-shadow:0 3px 10px #00000045, inset 0 1px 0 #ffffff0d;
    font-size:1.1em; font-weight:700; color:var(--text);
    cursor:pointer; transition:transform .1s ease, box-shadow .15s ease, border-color .15s ease;
  }
  .icon-btn:active{
    transform:scale(.94);
    border-color:#2f4a80;
    box-shadow:0 1px 5px #00000045, inset 0 1px 0 #ffffff0a;
  }
  @media (hover:hover){
    .icon-btn:hover{border-color:#2c4676;}
  }

  /* ---------- Menu ---------- */
  #menu{padding:env(safe-area-inset-top,18px) 18px 18px; gap:14px;}
  #menu .top{padding-top:14px;}
  .profile-card{padding:16px 18px; display:flex; align-items:center; gap:14px; margin:14px 0;}
  .avatar{
    width:56px; height:56px; border-radius:50%; flex-shrink:0;
    background:radial-gradient(circle at 35% 30%, #7fd0ff, #1f6fe0 60%, #0b2f6b);
    box-shadow:0 0 24px #3fa9ffaa, inset -4px -4px 10px #00174066;
    position:relative;
  }
  .avatar::after{content:''; position:absolute; inset:8px; border-radius:50%; background:radial-gradient(circle at 40% 30%, #fff9, transparent 60%);}
  .profile-info{flex:1; min-width:0;}
  .profile-name{font-weight:800; font-size:1.05em;}
  .profile-level{color:var(--gold); font-size:.8em; font-weight:700; margin-top:2px;}
  .xpbar-track{height:8px; border-radius:6px; background:#0a1836; margin-top:8px; overflow:hidden; border:1px solid #1e3a6d;}
  .xpbar-fill{height:100%; background:linear-gradient(90deg,var(--blue),var(--blue-glow)); border-radius:6px; transition:width .4s ease; box-shadow:0 0 10px #3fa9ffaa;}

  /* ---------- Rank Badges (visual only — layered on the existing Level system) ---------- */
  .rank-badge-row{display:flex; align-items:center; gap:6px; margin-top:2px;}
  .rank-badge-svg{display:block; flex-shrink:0;}
  .rank-badge-name{font-size:.8em; font-weight:800; letter-spacing:.3px;}
  .rank-current-card{padding:16px 18px; display:flex; align-items:center; gap:16px; margin-bottom:14px;}
  .rank-current-card .rank-current-info{flex:1; min-width:0;}
  .rank-current-card .rank-current-title{font-size:.72em; color:var(--dim); font-weight:700; letter-spacing:.5px; text-transform:uppercase;}
  .rank-current-card .rank-current-name{font-size:1.25em; font-weight:900; margin-top:2px;}
  .rank-current-card .rank-current-sub{font-size:.75em; color:var(--dim); margin-top:2px;}
  .rank-strip{display:flex; gap:12px; overflow-x:auto; padding:2px 2px 16px; -webkit-overflow-scrolling:touch;}
  .rank-strip-item{display:flex; flex-direction:column; align-items:center; gap:6px; min-width:60px; opacity:.4; flex-shrink:0;}
  .rank-strip-item.reached{opacity:.85;}
  .rank-strip-item.current{opacity:1;}
  .rank-strip-item .rank-strip-label{font-size:.62em; font-weight:800; text-align:center; letter-spacing:.2px;}
  .rank-strip-item.current .rank-strip-label{color:var(--gold);}
  @keyframes apexPulse{0%,100%{filter:brightness(1) saturate(1);} 50%{filter:brightness(1.4) saturate(1.3);}}
  .apex-pulse-ring{animation:apexPulse 2.1s ease-in-out infinite; transform-origin:22px 22px;}
  .xp-label{font-size:.7em; color:var(--dim); margin-top:4px;}
  .best-score{text-align:right; flex-shrink:0;}
  .best-score .num{font-weight:900; font-size:1.3em; color:var(--gold); text-shadow:0 0 12px #ffce5477;}
  .best-score .lbl{font-size:.65em; color:var(--dim); letter-spacing:1px;}

  .menu-buttons{display:flex; flex-direction:column; gap:12px; margin-top:6px;}
  #menu .profile-card{
    background:linear-gradient(145deg,#6c829b26,#132847e8 58%,#09162fe8);
    border-color:#82a9cc3d;
    box-shadow:0 12px 30px #00000070,inset 0 1px 0 #ffffff18,inset 0 0 0 1px #7eb6e918;
  }
  #menu .menu-buttons .btn{
    min-height:58px; border-radius:15px;
    background:linear-gradient(180deg,#34577dbb,#112846f2 54%,#0a1730f5);
    border-color:#6f9bc455;
  }
  #menu .menu-buttons .btn.primary{
    background:linear-gradient(180deg,#59b7f4,#2478c8 52%,#14508c);
    border-color:#a7e1ff66;
  }
  #menu .menu-row .btn{
    border-radius:14px;
    background:linear-gradient(180deg,#1b3155e8,#0b1832f5);
    border-color:#50759f42;
  }
  .menu-buttons .btn{padding:20px; font-size:1.15em;}
  .menu-row{display:flex; gap:12px;}
  .menu-row .btn{flex:1; flex-direction:column; padding:14px 8px; font-size:.85em; gap:6px;}
  .menu-row .btn span.big{font-size:1.6em;}

  .challenges{margin-top:16px; padding:14px 16px;}
  .challenges h3{margin:0 0 10px; font-size:.85em; letter-spacing:1px; color:var(--dim); text-transform:uppercase; display:flex; align-items:center; justify-content:space-between;}
  .streak-badge{font-size:1.15em; letter-spacing:0; text-transform:none; color:var(--gold); font-weight:800; text-shadow:0 0 8px #ffce5455; display:none;}
  .streak-badge.show{display:inline;}
  .challenge-item{display:flex; align-items:center; gap:10px; padding:8px 0; border-top:1px solid #ffffff0f;}
  .challenge-item:first-child{border-top:none;}
  .challenge-check{width:22px; height:22px; border-radius:6px; border:2px solid #3fa9ff88; flex-shrink:0; display:flex; align-items:center; justify-content:center; font-size:.8em;}
  .challenge-check.done{background:var(--green); border-color:var(--green); box-shadow:0 0 10px #37e39a88;}
  .challenge-text{flex:1; font-size:.85em;}
  .challenge-text .prog{color:var(--dim); font-size:.85em;}
  .challenge-reward{font-size:.75em; color:var(--gold); font-weight:700;}
  .challenge-item.done .challenge-reward{color:var(--green);}
  .challenge-progress-bar{height:5px; border-radius:4px; background:#0a1836; overflow:hidden; margin-top:5px; border:1px solid #ffffff10;}
  .challenge-progress-bar .fill{height:100%; background:linear-gradient(90deg,#3fa9ff,#5ec2ff); border-radius:4px; transition:width .25s ease;}
  .challenge-item.done .challenge-progress-bar .fill{background:linear-gradient(90deg,#37e39a,#5ffcb1);}

  /* ---------- Game screen ---------- */
  #gameScreen{
    background:
      radial-gradient(900px 560px at 50% 45%, #17387330, transparent 68%),
      radial-gradient(620px 420px at 12% 18%, #24599a16, transparent 70%),
      radial-gradient(700px 500px at 88% 82%, #071a3a28, transparent 72%),
      linear-gradient(180deg,#07132d 0%,#040b1b 54%,#020611 100%);
    isolation:isolate;
  }
  #gameScreen::before{
    content:""; position:absolute; inset:-18%; pointer-events:none; z-index:0;
    background:
      radial-gradient(260px 180px at 18% 28%, #5ec2ff0d, transparent 70%),
      radial-gradient(320px 220px at 78% 70%, #3fa9ff0a, transparent 72%);
    animation:arenaAmbientDrift 18s ease-in-out infinite alternate;
    transform:translate3d(0,0,0);
  }
  #gameScreen::after{
    content:""; position:absolute; inset:0; pointer-events:none; z-index:1;
    background:radial-gradient(ellipse at center, transparent 45%, #00000035 100%);
    opacity:.72;
  }
  #gameCanvas{z-index:2;}
  @keyframes arenaAmbientDrift{
    0%{transform:translate3d(-1.5%,-1%,0) scale(1);}
    100%{transform:translate3d(1.5%,1%,0) scale(1.035);}
  }
  #gameCanvas{position:absolute; inset:0; width:100%; height:100%; touch-action:none;}
  .hud{position:absolute; top:0; left:0; right:0; padding:calc(env(safe-area-inset-top,0px) + 10px) calc(env(safe-area-inset-right,0px) + 14px) 0 calc(env(safe-area-inset-left,0px) + 14px); display:flex; justify-content:space-between; align-items:flex-start; pointer-events:none; z-index:5;}
  .hud-left, .hud-right{display:flex; flex-direction:column; gap:6px; pointer-events:auto;}
  .hud-right{margin-top:52px;} /* clears the pause button so MP badges never sit under it */
  .hud-pill{padding:8px 14px; border-radius:20px; font-size:.85em; font-weight:700; display:flex; align-items:center; gap:6px;}
  .score-pill{font-size:1.3em; color:var(--gold); text-shadow:0 0 10px #ffce5488;}
  .timer-pill{font-variant-numeric:tabular-nums;}
  .timer-pill.timer-danger{color:var(--red); text-shadow:0 0 12px #ff4d6aaa; animation:dangerPulse 1s ease-in-out infinite;}

  /* ---------- Next-match countdown ---------- */
  .countdown-overlay{
    position:absolute; inset:0; z-index:50; display:none; align-items:center; justify-content:center;
    background:#020510cc; backdrop-filter:blur(3px);
  }
  .countdown-overlay.show{display:flex;}
  .countdown-text{
    font-size:6em; font-weight:900; color:var(--blue-glow);
    text-shadow:0 0 40px #3fa9ffaa; transform:scale(.6); opacity:0;
  }
  .countdown-text.pulse{ animation:countdownPulse .7s ease-out; }
  @keyframes countdownPulse{
    0%{ transform:scale(.6); opacity:0; }
    30%{ transform:scale(1.15); opacity:1; }
    70%{ transform:scale(1); opacity:1; }
    100%{ transform:scale(1); opacity:0; }
  }
  .combo-wrap{position:absolute; top:calc(env(safe-area-inset-top,0px) + 70px); left:50%; transform:translateX(-50%); text-align:center; pointer-events:none; z-index:5;}
  .combo-text{font-size:2em; font-weight:900; color:var(--gold); text-shadow:0 0 20px #ffce54cc; opacity:0; transform:scale(.7); transition:all .18s ease;}
  .combo-text.show{opacity:1; transform:scale(1);}

  /* ============================== POLARIX TRAINING overlay ==============================
     pointer-events:none on the whole layer so the joystick/polarity zones underneath stay fully
     usable; only the finish panel (with its PLAY button) re-enables pointer-events. */
  .tutorial-overlay{position:absolute; inset:0; z-index:45; display:none; pointer-events:none;}
  .tutorial-overlay.show{display:block;}
  .tutorial-banner{
    position:absolute; left:50%; top:calc(env(safe-area-inset-top,0px) + 70px); transform:translateX(-50%);
    width:min(88%,420px); padding:14px 20px; text-align:center; pointer-events:none;
  }
  .tutorial-step-num{font-size:.65em; letter-spacing:3px; color:var(--dim); font-weight:800; margin-bottom:4px;}
  .tutorial-step-label{font-size:1.35em; font-weight:900; letter-spacing:2px; color:var(--gold); text-shadow:0 0 14px #ffce5488; margin-bottom:6px;}
  .tutorial-step-text{font-size:.85em; color:var(--text); line-height:1.4;}
  .tutorial-arrow{
    position:absolute; font-size:2.6em; color:var(--gold); text-shadow:0 0 18px #ffce54cc;
    opacity:0; pointer-events:none; animation:tutorialBounce 1.1s ease-in-out infinite;
  }
  .tutorial-arrow.show{opacity:1;}
  #tutorialArrowJoystick{right:16%; bottom:32%;}
  #tutorialArrowPolarity{left:16%; bottom:32%;}
  @keyframes tutorialBounce{0%,100%{transform:translateY(0);} 50%{transform:translateY(-10px);}}
  .tutorial-finish{
    position:absolute; inset:0; display:none; flex-direction:column; align-items:center; justify-content:center;
    gap:14px; pointer-events:auto; background:radial-gradient(circle at 50% 42%, #0d1a40ee, #050914f5); z-index:2;
  }
  .tutorial-finish.show{display:flex;}
  .tutorial-finish-title{font-size:1.6em; font-weight:900; letter-spacing:2px; color:var(--gold); text-shadow:0 0 22px #ffce5488; text-align:center; padding:0 20px;}
  .tutorial-finish-sub{color:var(--dim); font-size:.95em;}
  #btnTutorialPlay{min-width:200px; text-align:center; margin-top:8px;}
  /* Hides the countdown-style match timer during training so it doesn't read like a real match is expiring */
  .tutorial-mode .timer-pill{display:none;}
  .danger-wrap{position:absolute; top:calc(env(safe-area-inset-top,0px) + 132px); left:50%; transform:translateX(-50%); text-align:center; pointer-events:none; z-index:5; opacity:0; transition:opacity .35s ease;}
  .danger-wrap.show{opacity:1;}
  .danger-badge{display:flex; align-items:center; gap:8px; padding:7px 16px; border-radius:20px; background:#3a0d14dd; border:1px solid #ff4d6a88; color:#ff9aac; font-weight:800; font-size:.8em; letter-spacing:.5px; box-shadow:0 0 14px #ff4d6a55; animation:dangerPulse 1s ease-in-out infinite;}
  .danger-arrow{display:inline-block; font-size:1.1em; transition:transform .25s ease;}
  @keyframes dangerPulse{0%,100%{box-shadow:0 0 10px #ff4d6a55;} 50%{box-shadow:0 0 20px #ff4d6aaa;}}

  /* ---------- Event banner (Magnetic Storm / Bounty announcements) ---------- */
  .event-banner{
    position:absolute; top:calc(env(safe-area-inset-top,0px) + 96px); left:50%;
    transform:translateX(-50%) scale(.85); text-align:center; pointer-events:none; z-index:6;
    opacity:0; transition:opacity .3s ease, transform .3s ease;
    padding:10px 22px; border-radius:16px; min-width:220px; max-width:86vw;
  }
  .event-banner.show{opacity:1; transform:translateX(-50%) scale(1);}
  .event-banner-title{font-size:1.1em; font-weight:900; letter-spacing:.5px; text-shadow:0 0 14px currentColor;}
  .event-banner-sub{font-size:.75em; font-weight:700; opacity:.9; margin-top:2px; letter-spacing:.4px;}
  .event-banner.storm{border:1px solid #5ec2ff88; box-shadow:0 0 26px #5ec2ff55; color:#8fd4ff;}
  .event-banner.storm .event-banner-title{color:#8fd4ff;}
  .event-banner.bounty{border:1px solid #ffce5488; box-shadow:0 0 26px #ffce5455; color:#ffe08a;}
  .event-banner.bounty .event-banner-title{color:#ffce54;}
  .event-banner.bountyplayer{border:1px solid #ff4d6a88; box-shadow:0 0 26px #ff4d6a55; color:#ff9aac;}
  .event-banner.bountyplayer .event-banner-title{color:#ff4d6a;}
  .event-banner.claim{border:1px solid #37e39a88; box-shadow:0 0 26px #37e39a55; color:#8ff5c8;}
  .event-banner.claim .event-banner-title{color:#37e39a;}

  /* ---------- Storm / Bounty HUD pills ---------- */
  .storm-pill{color:#8fd4ff; border:1px solid #5ec2ff55; animation:stormPillPulse 1s ease-in-out infinite;}
  .bounty-pill{color:#ff9aac; border:1px solid #ff4d6a55; animation:dangerPulse 1s ease-in-out infinite;}
  @keyframes stormPillPulse{0%,100%{box-shadow:0 0 8px #5ec2ff55;} 50%{box-shadow:0 0 18px #5ec2ffaa;}}

  #pauseBtn{position:absolute; top:calc(env(safe-area-inset-top,0px) + 10px); right:calc(env(safe-area-inset-right,0px) + 14px); z-index:6;}

  .joystick-zone{position:absolute; right:0; bottom:0; width:50%; height:55%; z-index:4; touch-action:none;}
  /* Idle/home position: right+bottom anchors so the control is visible the moment the HUD
     loads, before any touch. joyStart() below still switches this to explicit left/top
     (via inline style, which overrides right/bottom once width+left are both set) to make
     it float to the finger's touch point — that existing behavior is unchanged.
     width/height stay at 130px to exactly match the JS constant JOY_BASE_R (65 = half of
     130), so the visual ring and the movement math it's paired with stay in sync. */
  .joystick-base{
    position:absolute; width:130px; height:130px; border-radius:50%;
    right:14%; bottom:16%;
    background:radial-gradient(circle at 32% 26%, #1c2f57 0%, #14224a 22%, #0c1730 60%, #060b1a 100%);
    border:1.5px solid #5ec2ff55;
    box-shadow:
      0 10px 22px #00000088,
      0 0 22px 2px #3fa9ff33,
      inset 0 3px 8px #6fc6ff2e,
      inset 0 -14px 26px #00000099,
      inset 0 0 0 5px #0a1836b3;
    touch-action:none;
    transition:box-shadow .18s ease;
  }
  /* Recessed inner ring — reinforces the "socket the knob sits in" depth cue. */
  .joystick-base::before{
    content:''; position:absolute; inset:9px; border-radius:50%;
    border:1px solid #3fa9ff26;
    box-shadow:inset 0 0 16px #00000090, inset 0 0 18px #3fa9ff1f;
    pointer-events:none;
  }
  /* Soft ambient outer glow ring with a slow breathing pulse — reads as "powered on" /
     futuristic without needing any image asset. Purely decorative: pointer-events:none so
     it can never steal touches from #joyZone underneath. */
  .joystick-base::after{
    content:''; position:absolute; inset:-7px; border-radius:50%;
    border:1px solid #3fa9ff40;
    box-shadow:0 0 16px #3fa9ff4d;
    opacity:.6; pointer-events:none;
    animation:joyBasePulse 2.6s ease-in-out infinite;
  }
  @keyframes joyBasePulse{
    0%,100%{ transform:scale(1); opacity:.5; }
    50%{ transform:scale(1.055); opacity:.85; }
  }
  /* Toggled by JS (joyStart/joyEnd) purely for the glow-brighter feedback while dragging —
     does not touch joyVec/JOY_MAX/JOY_BASE_R or any movement math. */
  .joystick-base.active{
    box-shadow:
      0 10px 26px #000000aa,
      0 0 32px 6px #3fa9ff66,
      inset 0 3px 8px #8fd4ff4d,
      inset 0 -14px 26px #000000aa,
      inset 0 0 0 5px #0a1836b3;
  }
  /* Raised 3D knob: layered radial-gradient + light-from-top-left / shadow-to-bottom-right
     box-shadows simulate a physically raised, glossy sci-fi cap — no image, no flat fill.
     Size/position are still driven purely by joyStart/joyMove setting left/top in JS; only
     the "returning" class (added on release, removed on the next touch) adds a transition
     so the snap-back is smooth without ever slowing down live dragging. */
  .joystick-nub{
    position:absolute; width:68px; height:68px; border-radius:50%; top:50%; left:50%;
    background:radial-gradient(circle at 32% 24%, #d8f2ff 0%, #7fd0ff 32%, #2f84e6 66%, #0b2f6b 100%);
    box-shadow:
      0 7px 14px #001433cc,
      0 2px 5px #00000070,
      inset 0 4px 7px #eaf7ffcc,
      inset 0 -7px 12px #04255ecc,
      0 0 22px #3fa9ffcc;
    transform:translate(-50%,-50%);
    touch-action:none;
  }
  .joystick-nub.returning{
    transition:left .18s cubic-bezier(.34,1.56,.64,1), top .18s cubic-bezier(.34,1.56,.64,1);
  }
  /* Small specular highlight — the "glossy sphere" cue that reads as 3D rather than a flat disc. */
  .joystick-nub::after{
    content:''; position:absolute; width:14px; height:14px; border-radius:50%;
    top:15%; left:24%;
    background:radial-gradient(circle, #ffffffd9, #ffffff00 72%);
    pointer-events:none;
  }
  .polarity-zone{position:absolute; left:0; bottom:0; width:50%; height:55%; z-index:4; display:flex; align-items:flex-end; justify-content:flex-start; padding:0 0 calc(env(safe-area-inset-bottom,0px) + 26px) calc(env(safe-area-inset-left,0px) + 26px); touch-action:none;}
  .polarity-btn{
    width:92px; height:92px; border-radius:50%; display:flex; align-items:center; justify-content:center;
    font-size:0; font-weight:900; border:none; cursor:pointer; color:#fff;
    background-image:url('data:image/png;base64,');
    background-size:contain; background-position:center center; background-repeat:no-repeat; background-color:transparent;
    transition:transform .1s ease, filter .15s ease;
  }
  /* Polarity state is now conveyed with a colored glow around the new artwork instead of a
     background-color swap, since the artwork itself is the fixed visual asset for both states. */
  .polarity-btn.blue{box-shadow:0 0 26px #3fa9ffaa;}
  .polarity-btn.red{box-shadow:0 0 26px #ff4d6aaa;}
  .polarity-btn:active{transform:scale(.9);}

  .floating-score{position:absolute; font-weight:900; pointer-events:none; z-index:6; text-shadow:0 0 8px #000;}

  /* ---------- Game Over ---------- */
  #gameOverScreen{align-items:center; justify-content:center; padding:20px;}
  .go-panel{width:100%; max-width:420px; padding:26px 22px; text-align:center;}
  .go-title{font-size:1.6em; font-weight:900; color:var(--green); text-shadow:0 0 20px #37e39a88; margin-bottom:4px;}
  .go-title.lose{color:var(--red); text-shadow:0 0 20px #ff4d6a88;}
  .go-title.win{color:var(--gold); text-shadow:0 0 20px #ffce5488;}
  .go-sub2{font-weight:800; letter-spacing:1px; font-size:1em; margin-bottom:8px; color:var(--dim);}
  .go-sub2.win{color:var(--gold);}
  .go-sub2.lose{color:var(--red-glow);}
  .go-sub{color:var(--dim); font-size:.85em; margin-bottom:16px;}
  .go-stats{display:grid; grid-template-columns:1fr 1fr 1fr; gap:10px; margin:16px 0;}
  .go-stat{background:#0a1836; border:1px solid var(--panel-line); border-radius:12px; padding:10px 6px;}
  .go-stat .v{font-size:1.15em; font-weight:900; color:var(--blue-glow);}
  .go-stat .l{font-size:.6em; color:var(--dim); letter-spacing:.5px; margin-top:2px;}
  .go-xp{margin:10px 0; padding:10px; border-radius:12px; background:#101f45; color:var(--gold); font-weight:800; font-size:.95em;}
  .go-buttons{display:flex; gap:10px; margin-top:14px;}
  .go-buttons .btn{flex:1;}

  /* Match reward banner */
  .match-reward-banner{
    padding:14px 16px; margin-bottom:14px; text-align:center;
    border:1px solid #ffce5455; box-shadow:0 0 22px #ffce5422, inset 0 1px 0 #ffffff1a;
  }
  .match-reward-banner .mrb-label{font-size:.72em; letter-spacing:2.5px; color:var(--dim); font-weight:800; margin-bottom:4px;}
  .match-reward-banner .mrb-amount{font-size:1.5em; font-weight:900; color:var(--gold); text-shadow:0 0 16px #ffce5488;}
  .match-reward-banner .mrb-coin-ic{display:inline-block;}
  .match-reward-banner.pop .mrb-coin-ic{animation:mrbCoinPop .6s ease;}
  @keyframes mrbCoinPop{0%{transform:scale(1) rotate(0);} 35%{transform:scale(1.35) rotate(-12deg);} 65%{transform:scale(1.1) rotate(8deg);} 100%{transform:scale(1) rotate(0);}}

  /* Shop tabs */
  .shop-tabs{display:flex; gap:8px; margin-bottom:14px; background:#0a1836; border-radius:14px; padding:4px;}
  .shop-tab{flex:1; text-align:center; padding:10px; border-radius:11px; font-weight:800; font-size:.82em; color:var(--dim); cursor:pointer; letter-spacing:.3px;}
  .shop-tab.active{background:linear-gradient(135deg,var(--blue),#1f6fe0); color:#fff; box-shadow:0 4px 14px #3fa9ff44;}

  /* Ball skin cards */
  .skin-card{display:flex; align-items:center; gap:14px; padding:14px; margin-bottom:12px; position:relative; overflow:hidden;}
  .skin-card.equipped{border-color:#37e39a55; box-shadow:0 0 20px #37e39a22;}
  .skin-preview-canvas{width:64px; height:64px; flex-shrink:0; background:radial-gradient(circle at 50% 50%, #0f1e42, #060c1f 75%); border-radius:14px; border:1px solid var(--panel-line);}
  .skin-info{flex:1; min-width:0;}
  .skin-info .skin-name{font-weight:800; font-size:.95em;}
  .skin-info .skin-price{font-size:.78em; color:var(--gold); font-weight:700; margin-top:3px;}
  .skin-requirements{display:flex; gap:6px; margin-top:6px; flex-wrap:wrap;}
  .skin-req-pill{font-size:.64em; font-weight:800; padding:3px 8px; border-radius:8px; letter-spacing:.2px; border:1px solid var(--panel-line); color:var(--dim); background:#0a1836; white-space:nowrap;}
  .skin-req-pill.met{color:var(--green); border-color:#37e39a55; background:#0d2b22cc;}
  .skin-req-pill.unmet{color:var(--gold); border-color:#ffce5444;}
  .skin-action{flex-shrink:0; display:flex; flex-direction:column; gap:6px; align-items:stretch;}
  .skin-action .btn{min-width:78px; padding:9px 10px; font-size:.78em;}
  .skin-equipped-tag{color:var(--green)!important; border-color:#37e39a55!important; pointer-events:none;}

  /* BOSS-tier skins (Inferno / Aqua) — same card layout, just a hotter frame + badge */
  .skin-card.boss{border-color:#ffce5477; box-shadow:0 0 22px #ffce5433; background:linear-gradient(135deg,#1a1330dd,#0e1a3aee);}
  .skin-card.boss.equipped{border-color:#37e39a77; box-shadow:0 0 22px #37e39a33;}
  .skin-boss-badge{display:inline-block; font-size:.62em; font-weight:900; letter-spacing:.4px; padding:2px 7px; border-radius:7px; margin-left:6px; vertical-align:middle; color:#1a1330; background:linear-gradient(90deg,#ffce54,#ff7d92); box-shadow:0 0 8px #ffce5455;}

  /* Coins IAP packs — dedicated premium in-game store look */
  .coin-shop-header{display:flex; align-items:center; gap:12px; padding:14px 16px; margin-bottom:14px; position:relative; overflow:hidden; border:1px solid #ffce5455; background:linear-gradient(135deg,#241a0af5,#0e1a3aee); box-shadow:0 0 26px #ffce5422, inset 0 1px 0 #ffffff14;}
  .coin-shop-header-icon{width:46px; height:46px; border-radius:13px; display:flex; align-items:center; justify-content:center; font-size:1.5em; flex-shrink:0; background:radial-gradient(circle at 35% 30%, #3a2a0a, #0a1836 70%); border:1px solid #ffce5455; box-shadow:0 0 14px #ffce5433;}
  .coin-shop-header-text{flex:1; min-width:0;}
  .coin-shop-title{font-size:1.05em; font-weight:900; letter-spacing:1px; color:var(--gold); text-shadow:0 0 14px #ffce5455;}
  .coin-shop-sub{font-size:.72em; color:var(--dim); margin-top:2px;}
  .coin-iap-note{font-size:.72em; color:var(--dim); text-align:center; margin:2px 4px 16px; line-height:1.5;}
  .coin-pack-card{display:flex; align-items:center; gap:14px; padding:16px; margin-bottom:14px; position:relative; overflow:hidden; border:1px solid #ffce5433; background:linear-gradient(135deg,#14203fee,#0b132eee); box-shadow:0 8px 24px #00000055, inset 0 1px 0 #ffffff14;}
  .coin-pack-icon{width:56px; height:56px; border-radius:15px; display:flex; align-items:center; justify-content:center; font-size:1.8em; flex-shrink:0; background:radial-gradient(circle at 35% 30%, #3a2a0a, #0a1836 70%); border:1px solid #ffce5455; box-shadow:0 0 16px #ffce5433;}
  .coin-pack-info{flex:1; min-width:0;}
  .coin-pack-info .name{font-weight:800; font-size:.95em;}
  .coin-pack-info .amount{font-size:.88em; color:var(--gold); font-weight:900; margin-top:4px; text-shadow:0 0 10px #ffce5444;}
  .coin-pack-info .price{display:inline-block; font-size:.74em; color:var(--text); font-weight:800; margin-top:6px; padding:3px 9px; border-radius:8px; background:#0a1836; border:1px solid var(--panel-line);}
  .coin-pack-card.best-value{border-color:#ffce54aa; box-shadow:0 0 24px #ffce5444;}
  .coin-pack-badge{display:inline-block; font-size:.6em; font-weight:900; letter-spacing:.3px; padding:2px 7px; border-radius:7px; margin-left:6px; vertical-align:middle; color:#1a1330; background:linear-gradient(90deg,#ffce54,#ff7d92);}
  .coin-pack-action{flex-shrink:0;}
  .coin-pack-action .btn{min-width:84px; padding:11px 12px; font-size:.82em; font-weight:900; letter-spacing:.5px;}

  /* Boss skin TRY (trial) button — visually distinct from BUY, reward/trial styled */
  .skin-try-btn{background:linear-gradient(135deg,#1c3a2eee,#0e2820ee)!important; border-color:#37e39a66!important; color:var(--green)!important; box-shadow:0 4px 14px #37e39a22, inset 0 1px 0 #ffffff14!important;}

  /* Trial Arena */
  .trial-arena-card{padding:22px 18px; text-align:center; margin-bottom:16px;}
  .trial-arena-badge{display:inline-block; font-size:.68em; font-weight:900; letter-spacing:.4px; padding:4px 10px; border-radius:8px; color:#1a1330; background:linear-gradient(90deg,#ffce54,#ff7d92); box-shadow:0 0 10px #ffce5455; margin-bottom:14px;}
  .trial-arena-canvas-wrap{width:180px; height:180px; margin:0 auto 16px; border-radius:22px; background:radial-gradient(circle at 50% 40%, #16224a, #060c1f 75%); border:1px solid var(--panel-line); box-shadow:0 0 30px #00000066, inset 0 0 40px #00000055; display:flex; align-items:center; justify-content:center; position:relative; overflow:hidden;}
  .trial-arena-canvas-wrap::before{content:''; position:absolute; inset:0; background-image:radial-gradient(#ffffff12 1px, transparent 1px); background-size:16px 16px; opacity:.5;}
  .trial-arena-name{font-size:1.3em; font-weight:900; margin-bottom:4px;}
  .trial-arena-timer{font-size:.85em; color:var(--gold); font-weight:800; margin-top:10px;}
  .trial-arena-note{font-size:.74em; color:var(--dim); line-height:1.5; margin:14px 4px 4px;}

  /* Rank list (VIEW RANKS screen) */
  .rank-progress-track{height:10px; border-radius:6px; background:#0a1836; border:1px solid var(--panel-line); overflow:hidden; margin-top:10px;}
  .rank-progress-fill{height:100%; border-radius:6px; background:linear-gradient(90deg,var(--blue),var(--gold)); box-shadow:0 0 10px #ffce5455;}
  .rank-next-label{font-size:.72em; color:var(--dim); margin-top:8px;}
  .rank-list-item{display:flex; align-items:center; gap:14px; padding:14px; margin-bottom:10px; opacity:.55;}
  .rank-list-item.reached{opacity:1;}
  .rank-list-item.current{opacity:1; border-color:var(--gold); box-shadow:0 0 20px #ffce5433;}
  .rank-list-badge{flex-shrink:0; width:44px; height:44px; display:flex; align-items:center; justify-content:center;}
  .rank-list-info{flex:1; min-width:0;}
  .rank-list-name{font-weight:900; font-size:.98em; display:flex; align-items:center; gap:6px;}
  .rank-list-req{font-size:.72em; color:var(--dim); margin-top:2px;}
  .rank-list-tag{flex-shrink:0; font-size:.62em; font-weight:900; letter-spacing:.3px; padding:4px 9px; border-radius:8px;}
  .rank-list-tag.current{color:#1a1330; background:linear-gradient(90deg,#ffce54,#ff7d92);}
  .rank-list-tag.reached{color:var(--green); border:1px solid #37e39a55; background:#0d2b22cc;}
  .rank-list-tag.locked{color:var(--dim); border:1px solid var(--panel-line); background:#0a1836;}

  /* Room Cards — premium Private Room currency (Free Fire style) */
  .room-cards-box{padding:16px 18px; text-align:center; margin-top:16px; border:1px solid #ffce5444; background:linear-gradient(180deg,#241a0af5,#160f06f5); box-shadow:0 0 0 1px #ffce5422 inset, 0 0 26px #ffce5422;}
  .room-cards-label{font-size:.7em; color:var(--dim); letter-spacing:3px; margin-bottom:8px; font-weight:800;}
  .room-cards-row{display:flex; align-items:center; justify-content:center; gap:14px; flex-wrap:wrap;}
  .room-cards-value{font-size:1.6em; font-weight:900; color:var(--gold); text-shadow:0 0 16px #ffce5488;}
  .room-cards-hint{margin-top:10px; font-size:.72em; color:var(--dim);}

  /* ---------- Friends, Chat & Private Room Invites ---------- */
  .id-box{padding:16px 18px; text-align:center; margin-bottom:16px; border:1px solid #5ec2ff44; background:linear-gradient(180deg,#0e1a3af5,#0a1330f5); box-shadow:0 0 0 1px #5ec2ff1a inset, 0 0 26px #3fa9ff22;}
  .id-box-label{font-size:.7em; color:var(--dim); letter-spacing:3px; margin-bottom:8px; font-weight:800;}
  .id-box-row{display:flex; align-items:center; justify-content:center; gap:14px; flex-wrap:wrap;}
  .id-box-value{font-size:1.02em; font-weight:900; letter-spacing:1px; color:var(--blue-glow); text-shadow:0 0 14px #3fa9ffaa; word-break:break-all; cursor:pointer; -webkit-tap-highlight-color:transparent;}
  .id-box-value:active{opacity:0.6;}
  .id-box-hint{margin-top:8px; font-size:.7em; color:var(--dim);}
  /* Real-time player search (fills in as the user types, Free-Fire-style) */
  .friend-search-results{display:none; margin:-6px 0 16px; max-height:52vh; overflow-y:auto;}
  .search-result-row .friend-status-text{white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
  .friend-search-empty{text-align:center; color:var(--dim); font-size:.78em; padding:12px 10px;}
  .friends-search-row{display:flex; gap:8px; margin-bottom:16px;}
  .friends-search-row input{
    flex:1; padding:13px 14px; border-radius:12px; border:1px solid var(--panel-line);
    background:#0a1836; color:var(--text); font-size:.92em; outline:none; letter-spacing:1px;
  }
  .friends-search-row input:focus{border-color:var(--blue);}
  .friends-search-row .btn{flex-shrink:0; padding:12px 18px; font-size:.85em;}
  .friends-section-title{font-size:.72em; color:var(--dim); letter-spacing:2.5px; font-weight:800; margin:18px 4px 10px;}
  .friend-row{display:flex; align-items:center; gap:12px; padding:12px 14px; margin-bottom:8px; transition:transform .08s ease;}
  .friend-row .friend-avatar{width:38px; height:38px; border-radius:50%; flex-shrink:0; display:flex; align-items:center; justify-content:center; font-size:1.05em; background:radial-gradient(circle at 35% 30%,#7fd0ff,#1f6fe0 60%,#0b2f6b); box-shadow:0 0 12px #3fa9ff88; position:relative;}
  .friend-row .status-dot{position:absolute; right:-1px; bottom:-1px; width:11px; height:11px; border-radius:50%; background:var(--dim); border:2px solid var(--bg-navy);}
  .friend-row .status-dot.online{background:var(--green); box-shadow:0 0 8px #37e39aaa;}
  .friend-row.pinned{border-color:#ffce5455;}
  .friend-row.blocked{opacity:.62;}
  .friend-status-text.blocked{color:var(--red);}
  .friend-row-tappable{cursor:pointer;}
  .friend-row-tappable:active{transform:scale(.985);}
  .friend-chat-btn{min-width:80px;}
  .friend-pin-icon{font-size:.78em; margin-right:4px; opacity:.9;}
  .friend-mute-icon{font-size:.78em; margin-left:4px; opacity:.6;}
  .friend-row .friend-info{flex:1; min-width:0;}
  .friend-row .friend-name{font-weight:700; font-size:.92em; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
  .friend-row .friend-status-text{font-size:.68em; color:var(--dim); margin-top:2px;}
  .friend-row .friend-status-text.online{color:var(--green);}
  .friend-row .friend-actions{display:flex; gap:6px; flex-shrink:0;}
  .friend-row .friend-actions .btn{padding:8px 12px; font-size:.7em; min-width:0;}
  .friend-empty{text-align:center; color:var(--dim); font-size:.82em; padding:18px 10px; line-height:1.5;}

  /* Post-match "MATCH PLAYERS" list (Game Over screen, Multiplayer only) — add anyone from the
     match as a friend without leaving the result screen. */
  .match-players-box{padding:14px 16px; margin:12px 0; text-align:left;}
  .match-players-title{font-size:.72em; color:var(--dim); letter-spacing:2.5px; font-weight:800; margin-bottom:10px; text-align:center;}
  .match-players-list{max-height:22vh; overflow-y:auto; -webkit-overflow-scrolling:touch; touch-action:pan-y; display:flex; flex-direction:column; gap:8px;}
  .match-player-row{padding:10px 12px;}
  .request-row{display:flex; align-items:center; gap:10px; padding:12px 14px; margin-bottom:8px; border-color:#ffce5444;}
  .request-row .friend-info{flex:1; min-width:0;}
  .request-row .friend-name{font-weight:700; font-size:.9em;}
  .request-row .friend-actions{display:flex; gap:6px; flex-shrink:0;}
  .request-row .friend-actions .btn{padding:8px 11px; font-size:.68em; min-width:0;}
  .request-badge{display:inline-block; font-size:.62em; font-weight:900; padding:2px 8px; border-radius:8px; margin-left:6px; color:#1a1330; background:linear-gradient(90deg,#ffce54,#ff7d92); vertical-align:middle;}

  /* ---------- Report button (Friend profile / Friend request / Match result / Multiplayer player rows) ----------
     Small, understated flag icon — never a primary action, sits alongside each row's existing buttons. */
  .report-btn{
    display:flex; align-items:center; justify-content:center; flex-shrink:0;
    width:34px; height:34px; padding:0; border-radius:10px;
    background:linear-gradient(180deg,#101f45,#0a1330); border:1px solid #22335f;
    box-shadow:0 3px 10px #00000045, inset 0 1px 0 #ffffff0d;
    font-size:.9em; cursor:pointer; transition:transform .1s ease, border-color .15s ease;
  }
  .report-btn:active{transform:scale(.92); border-color:#ff4d6a66;}
  .mp-player-row .report-btn{margin-left:2px;}

  /* ---------- Report Reason modal ---------- */
  .report-modal{max-width:360px; text-align:left;}
  .report-modal .modal-title{text-align:center;}
  .report-target-name{text-align:center; color:var(--dim); font-size:.78em; margin:-8px 0 14px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
  .reason-list{display:flex; flex-direction:column; gap:8px;}
  .reason-opt{
    display:flex; align-items:center; gap:10px; padding:12px 14px; border-radius:12px;
    border:1px solid var(--panel-line); background:#0a1836; font-size:.85em; font-weight:600;
    cursor:pointer; transition:border-color .12s ease, background .12s ease;
  }
  .reason-opt .dot{width:16px; height:16px; border-radius:50%; border:2px solid var(--panel-line); flex-shrink:0; position:relative;}
  .reason-opt.selected{border-color:var(--red); background:#2a0f1a;}
  .reason-opt.selected .dot{border-color:var(--red);}
  .reason-opt.selected .dot::after{content:''; position:absolute; inset:3px; border-radius:50%; background:var(--red);}
  .report-error{color:var(--red); font-size:.75em; text-align:center; min-height:1.2em; margin-top:10px;}

  /* Chat (Lobby chat, Private Room chat, Friend DM chat) — compact, mobile-friendly, no flash */
  .chat-toggle{display:flex; align-items:center; justify-content:space-between; padding:11px 14px; margin-top:14px; cursor:pointer; font-size:.82em; font-weight:800; letter-spacing:.4px; color:var(--dim);}
  .chat-toggle .arrow{transition:transform .2s ease;}
  .chat-toggle.open .arrow{transform:rotate(180deg);}
  .chat-panel{display:none; margin-top:8px; padding:10px; flex-direction:column;}
  .chat-panel.open{display:flex;}
  .chat-list{height:34vh; max-height:220px; min-height:0; overflow-y:scroll; overflow-x:hidden; -webkit-overflow-scrolling:touch; touch-action:pan-y !important; overscroll-behavior-y:auto; pointer-events:auto; padding:4px 6px; display:flex; flex-direction:column; gap:6px;}
  .chat-msg{font-size:.8em; line-height:1.4; padding:6px 9px; border-radius:10px; background:#0a1836; border:1px solid var(--panel-line); word-break:break-word;}
  .chat-msg.me{background:#0f2a4d; border-color:#3fa9ff44;}
  .chat-msg-name{font-weight:800; color:var(--blue-glow); margin-right:6px;}
  .chat-msg-text{color:var(--text);}
  .chat-msg-time{float:right; font-size:.85em; color:var(--dim); margin-left:8px;}
  .chat-empty{text-align:center; color:var(--dim); font-size:.78em; padding:14px 6px;}
  .chat-input-row{display:flex; gap:8px; margin-top:10px;}
  .chat-input-row input{
    flex:1; padding:11px 13px; border-radius:12px; border:1px solid var(--panel-line);
    background:#0a1836; color:var(--text); font-size:.85em; outline:none;
  }
  .chat-input-row input:focus{border-color:var(--blue);}
  .chat-input-row .btn{flex-shrink:0; padding:11px 16px; font-size:.8em;}
  /* Friend DM Chat — dedicated FULL-SCREEN chat screen (not a popup/modal). Uses the same
     .screen system as every other page (Friends, Shop, etc.) so it takes 100% of the
     available width/height, survives back-navigation cleanly, and never overlaps or gets
     clipped by anything else. */
  .chat-screen{overflow:hidden; position:relative; touch-action:auto;}
  .chat-header{
    flex-shrink:0; display:flex; align-items:center; gap:12px;
    padding:max(env(safe-area-inset-top,14px),14px) 16px 12px;
    border-bottom:1px solid var(--panel-line);
    background:#060a18cc; backdrop-filter:blur(10px);
    box-shadow:0 4px 14px #00000030;
  }
  /* Friend Chat 3-dot menu — dropdown anchored under the header, closed by default */
  .chat-menu-dropdown{
    position:absolute; right:14px; top:max(env(safe-area-inset-top,14px),14px); margin-top:52px; z-index:60;
    background:linear-gradient(180deg,#101f45,#0a1330); border:1px solid #22335f; border-radius:14px;
    box-shadow:0 10px 30px #00000060, inset 0 1px 0 #ffffff0d; min-width:210px; padding:6px;
    display:none; backdrop-filter:blur(10px);
  }
  .chat-menu-dropdown.show{display:block;}
  .chat-menu-item{
    padding:11px 14px; font-size:.85em; font-weight:700; color:var(--text); border-radius:10px;
    display:flex; align-items:center; gap:10px; cursor:pointer; white-space:nowrap;
  }
  .chat-menu-item:active{background:#ffffff14;}
  .chat-menu-item.danger{color:var(--red);}
  .chat-menu-item .chat-menu-icon{width:18px; text-align:center; flex-shrink:0;}
  .chat-menu-backdrop{position:fixed; inset:0; z-index:55; display:none;}
  .chat-menu-backdrop.show{display:block;}
  /* Reply-to-message: quoted snippet rendered above the message text inside the bubble */
  .chat-reply-quote{
    border-left:3px solid #ffffff70; padding:4px 8px; margin-bottom:5px; border-radius:6px;
    background:#00000022; font-size:.86em; line-height:1.25;
  }
  .chat-reply-quote-name{display:block; font-weight:800; opacity:.95; font-size:.85em;}
  .chat-reply-quote-text{display:block; opacity:.85; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:100%;}
  /* Reply picking mode: hint the messages are tappable */
  .chat-body.reply-picking .chat-bubble{cursor:pointer; outline:1px dashed #5ec2ff55; outline-offset:2px;}
  /* Pending-reply preview bar shown above the input while composing a reply */
  .chat-reply-preview{
    flex-shrink:0; display:none; align-items:center; gap:10px;
    padding:8px 12px; border-top:1px solid var(--panel-line);
    background:#0a1836cc;
  }
  .chat-reply-preview.show{display:flex;}
  .chat-reply-preview-bar{width:3px; align-self:stretch; border-radius:3px; background:var(--blue-glow); flex-shrink:0;}
  .chat-reply-preview-content{flex:1; min-width:0;}
  .chat-reply-preview-name{font-size:.78em; font-weight:800; color:var(--blue-glow);}
  .chat-reply-preview-text{font-size:.82em; color:var(--dim); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
  .chat-reply-preview-cancel{flex-shrink:0; width:26px; height:26px; border-radius:50%; display:flex; align-items:center; justify-content:center; color:var(--dim); font-size:.9em; cursor:pointer;}
  .chat-reply-preview-cancel:active{background:#ffffff14;}
  .chat-header-info{flex:1; min-width:0;}
  .chat-header-name{font-weight:900; font-size:1em; letter-spacing:.3px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;}
  .chat-header-status{font-size:.72em; color:var(--dim); margin-top:2px; display:flex; align-items:center; gap:5px;}
  .chat-header-status .status-dot{width:7px; height:7px; border-radius:50%; background:var(--dim); flex-shrink:0;}
  .chat-header-status .status-dot.online{background:var(--green); box-shadow:0 0 6px #37e39aaa;}
  .chat-header-status.online{color:var(--green);}
  /* Full-height scrollable message area — the ONLY thing that scrolls; header and input bar
     stay pinned so the layout can never jump or half-collapse when the keyboard opens. */
  .chat-body{
    flex:1 1 0%; min-height:0; height:0; overflow-y:scroll; overflow-x:hidden;
    -webkit-overflow-scrolling:touch; touch-action:pan-y !important; overscroll-behavior-y:auto;
    pointer-events:auto; padding:14px 12px; display:flex; flex-direction:column; gap:7px;
  }
  .chat-bubble-row{display:flex; max-width:100%;}
  .chat-bubble-row.me{justify-content:flex-end;}
  .chat-bubble-row.them{justify-content:flex-start;}
  /* Bubbles: mine = blue "futuristic" accent (right side), theirs = red/orange accent (left
     side) — both readable light text on a dark-glass panel, matching the rest of the UI. */
  .chat-bubble{
    max-width:78%; padding:9px 12px 6px; border-radius:16px; font-size:.86em; line-height:1.36;
    word-break:break-word; overflow-wrap:anywhere; white-space:pre-wrap;
    box-shadow:0 3px 12px #00000038, inset 0 1px 0 #ffffff0f;
  }
  .chat-bubble.me{
    background:linear-gradient(160deg,#1c3a72,#132455);
    color:var(--text);
    border:1px solid #5ec2ff55; border-bottom-right-radius:5px;
  }
  .chat-bubble.them{
    background:linear-gradient(160deg,#7a2a1e,#4a1610);
    color:var(--text);
    border:1px solid #ff7d9255; border-bottom-left-radius:5px;
  }
  .chat-bubble-time{display:block; font-size:.66em; color:var(--dim); margin-top:3px; text-align:right;}
  /* Message delivery/read status ticks (WhatsApp-style), sender's own bubbles only. */
  .chat-msg-tick{margin-left:4px; color:var(--dim); letter-spacing:-1px;}
  .chat-msg-tick.read{color:var(--blue-glow);}
  .chat-empty{text-align:center; color:var(--dim); font-size:.8em; padding:26px 6px;}
  /* Fixed message input bar — flex-shrink:0 keeps it pinned to the bottom of the .chat-screen
     flex column; JS syncs the screen's height to window.visualViewport so this bar sits right
     above the on-screen keyboard instead of being pushed off/under it. */
  .chat-input-bar{
    flex-shrink:0; display:flex; gap:10px; align-items:center;
    padding:10px 12px calc(10px + env(safe-area-inset-bottom,0px));
    border-top:1px solid var(--panel-line);
    background:#060a18cc; backdrop-filter:blur(10px);
  }
  .chat-input-bar input{
    flex:1; min-width:0; padding:12px 16px; border-radius:22px; border:1px solid var(--panel-line);
    background:#0a1836; color:var(--text); font-size:.92em; outline:none;
  }
  .chat-input-bar input:focus{border-color:var(--blue-glow); box-shadow:0 0 0 3px #5ec2ff1f;}
  .chat-input-bar .btn{flex-shrink:0; padding:0 20px; height:44px; font-size:.8em; border-radius:22px; display:flex; align-items:center; justify-content:center;}
  .invite-modal .modal-title{color:var(--gold);}
  .invite-modal-text{font-size:.92em; color:var(--text); line-height:1.5; margin-bottom:6px;}

  /* ---------- Shop / Leaderboard / Settings ---------- */
  .subscreen{padding:env(safe-area-inset-top,18px) 16px 30px;}
  .subheader{display:flex; align-items:center; gap:12px; margin-bottom:16px;}
  .subheader h2{margin:0; font-size:1.3em; flex:1;}
  .coin-badge{padding:8px 14px; border-radius:14px; font-weight:800; color:var(--gold); font-size:.9em;}

  .shop-item{display:flex; align-items:center; gap:14px; padding:14px; margin-bottom:12px;}
  .shop-icon{width:48px; height:48px; border-radius:12px; display:flex; align-items:center; justify-content:center; font-size:1.5em; flex-shrink:0; background:#0a1836; border:1px solid var(--panel-line);}
  .shop-info{flex:1; min-width:0;}
  .shop-info .name{font-weight:800; font-size:.95em;}
  .shop-info .desc{font-size:.72em; color:var(--dim); margin-top:2px;}
  .shop-dots{display:flex; gap:4px; margin-top:6px;}
  .dot{width:16px; height:6px; border-radius:3px; background:#1e3a6d;}
  .dot.filled{background:var(--blue); box-shadow:0 0 6px #3fa9ffaa;}

  .lb-item{display:flex; align-items:center; gap:12px; padding:12px 14px; margin-bottom:8px;}
  .lb-rank{width:32px; text-align:center; font-weight:900; font-size:1.1em; color:var(--dim);}
  .lb-item.top1 .lb-rank{color:#ffd700;}
  .lb-item.top2 .lb-rank{color:#c8d0e0;}
  .lb-item.top3 .lb-rank{color:#e0a35c;}
  .lb-item.me{border-color:var(--blue); box-shadow:0 0 14px #3fa9ff44;}
  .lb-name{flex:1; font-weight:700; font-size:.92em;}
  .lb-score{font-weight:900; color:var(--gold); font-size:.95em;}

  .settings-row{display:flex; align-items:center; justify-content:space-between; padding:16px; margin-bottom:12px;}
  .settings-row .lbl{font-weight:700; font-size:.95em;}
  .toggle{width:52px; height:30px; border-radius:20px; background:#1e3a6d; position:relative; cursor:pointer; flex-shrink:0;}
  .toggle.on{background:var(--blue); box-shadow:0 0 12px #3fa9ff88;}
  .toggle .knob{position:absolute; top:3px; left:3px; width:24px; height:24px; border-radius:50%; background:#fff; transition:left .15s ease;}
  .toggle.on .knob{left:25px;}

  .toast{
    position:fixed; top:16px; left:50%; transform:translateX(-50%) translateY(-30px);
    padding:12px 20px; border-radius:14px; font-weight:700; font-size:.9em; z-index:999;
    opacity:0; transition:all .3s ease; pointer-events:none;
  }
  .toast.show{opacity:1; transform:translateX(-50%) translateY(0);}

  /* In-game chat message notification — compact card at the top of the screen, tappable,
     shown over any screen (see showChatNotification() in JS). Deliberately distinct from
     the plain .toast above so it reads as "someone messaged you", not a generic status pill. */
  .chat-notify-banner{
    position:fixed; top:max(env(safe-area-inset-top,10px),10px); left:50%;
    transform:translateX(-50%) translateY(-140%);
    width:min(92vw, 380px); max-width:calc(100vw - 24px);
    display:flex; align-items:center; gap:11px; padding:11px 14px;
    border-radius:16px; background:linear-gradient(160deg,#152a52f2,#0e1a3af2);
    border:1px solid #5ec2ff55; box-shadow:0 12px 30px #00000066, inset 0 1px 0 #ffffff14;
    backdrop-filter:blur(10px); z-index:1000; opacity:0; cursor:pointer;
    transition:transform .28s cubic-bezier(.34,1.4,.64,1), opacity .22s ease;
    pointer-events:none;
  }
  .chat-notify-banner.show{transform:translateX(-50%) translateY(0); opacity:1; pointer-events:auto;}
  .chat-notify-banner:active{transform:translateX(-50%) translateY(0) scale(.97);}
  .chat-notify-icon{
    width:34px; height:34px; border-radius:50%; flex-shrink:0; display:flex; align-items:center;
    justify-content:center; font-size:1.05em;
    background:radial-gradient(circle at 35% 30%,#7fd0ff,#1f6fe0 60%,#0b2f6b);
    box-shadow:0 0 10px #3fa9ff77;
  }
  .chat-notify-body{flex:1; min-width:0;}
  .chat-notify-name{font-weight:800; font-size:.86em; color:var(--blue-glow); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
  .chat-notify-msg{font-size:.8em; color:var(--text); margin-top:2px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; opacity:.92;}

  ::-webkit-scrollbar{width:0;}
  .profile-name{cursor:pointer; display:inline-flex; align-items:center; gap:6px;}
  .profile-name .edit-icon{font-size:.72em; opacity:.55;}
  .profile-name:active .edit-icon{opacity:1;}

  .modal-overlay{
    position:fixed; inset:0; z-index:200; display:none; align-items:center; justify-content:center;
    background:#020510cc; backdrop-filter:blur(4px); padding:20px;
  }
  .modal-overlay.show{display:flex;}
  .modal{width:100%; max-width:340px; padding:22px 20px; text-align:center;}
  .modal-title{font-weight:900; letter-spacing:1px; font-size:1.05em; margin-bottom:14px; color:var(--blue-glow);}
  .modal input{
    width:100%; padding:14px 16px; border-radius:12px; border:1px solid var(--panel-line);
    background:#0a1836; color:var(--text); font-size:1em; text-align:center; outline:none;
  }
  .modal input:focus{border-color:var(--blue);}
  .modal-buttons{display:flex; gap:10px; margin-top:16px;}
  .modal-buttons .btn{flex:1;}
  .pause-modal{
    max-width:420px; padding:22px 20px 24px; border-radius:20px;
    background:linear-gradient(180deg,#7489a633,#3a527766 38%,#101d3bef 100%);
    border:1px solid #8eb5dc55;
    box-shadow:0 18px 48px #000000aa,inset 0 1px 0 #ffffff24,inset 0 0 0 1px #b9d9f51a;
    backdrop-filter:blur(18px) saturate(125%);
  }
  .pause-modal-head{display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:20px;}
  .pause-modal-title{
    display:flex; align-items:center; gap:10px; min-width:0;
    font-weight:900; letter-spacing:1.5px; font-size:1.12em; color:#eef7ff;
    text-shadow:0 2px 10px #00000088,0 0 16px #8fd4ff30;
  }
  .pause-title-icon{font-size:1.25em; line-height:1; color:#cceaff; text-shadow:0 0 10px #5ec2ff88;}
  .pause-settings-btn{
    width:42px; height:42px; min-width:42px; border-radius:13px; color:#d7eaff; font-size:1.15em;
    background:linear-gradient(180deg,#91a9bf33,#20375866); border-color:#c5ddf244;
  }
  .pause-modal-buttons{display:flex; flex-direction:column; gap:12px; margin-top:2px;}
  .pause-modal-buttons .btn{width:100%; min-height:56px; border-radius:14px; font-weight:900; letter-spacing:1px;}
  .pause-action{
    background:linear-gradient(180deg,#4c7098cc 0%,#17355dcc 48%,#0b1b36e8 100%);
    border:1px solid #9bc4ea55; box-shadow:0 7px 18px #00000055,inset 0 1px 0 #ffffff25;
  }
  .pause-action.primary{
    background:linear-gradient(180deg,#5aa7e8 0%,#1e67a9 52%,#103e70 100%);
    border-color:#9ddcff88; box-shadow:0 8px 22px #1676c955,inset 0 1px 0 #ffffff38;
  }
  .pause-action:active{transform:scale(.985);}
  #btnPauseRestart[style*="display: none"]{display:none !important;}

  /* ---------- Multiplayer ---------- */
  .mp-badge{padding:6px 12px; border-radius:12px; font-size:.7em; font-weight:800; letter-spacing:.5px; display:flex; align-items:center; gap:6px;}
  .mp-badge .dot{width:8px; height:8px; border-radius:50%; background:var(--green); box-shadow:0 0 8px #37e39aaa;}
  .mp-badge.reconnecting .dot{background:var(--gold); box-shadow:0 0 8px #ffce54aa; animation:dangerPulse 1s ease-in-out infinite;}
  .mp-badge.offline .dot{background:var(--red); box-shadow:0 0 8px #ff4d6aaa;}

  /* ---------- Lobby: animated sci-fi backdrop ---------- */
  #mpLobbyScreen{position:relative; overflow:hidden;}
  #mpLobbyScreen::before{
    content:''; position:absolute; inset:-2px; z-index:0; pointer-events:none;
    background-image:
      linear-gradient(#5ec2ff14 1px, transparent 1px),
      linear-gradient(90deg, #5ec2ff14 1px, transparent 1px);
    background-size:34px 34px;
    -webkit-mask-image: radial-gradient(circle at 50% 15%, #000 0%, transparent 72%);
    mask-image: radial-gradient(circle at 50% 15%, #000 0%, transparent 72%);
    animation: lobbyGridDrift 16s linear infinite;
  }
  #mpLobbyScreen::after{
    content:''; position:absolute; inset:0; z-index:0; pointer-events:none;
    background:
      radial-gradient(3px 3px at 15% 22%, #5ec2ff99, transparent 60%),
      radial-gradient(2px 2px at 80% 14%, #b06bff88, transparent 60%),
      radial-gradient(2px 2px at 40% 68%, #5ec2ff66, transparent 60%),
      radial-gradient(3px 3px at 88% 55%, #b06bff77, transparent 60%),
      radial-gradient(2px 2px at 60% 38%, #5ec2ff55, transparent 60%),
      radial-gradient(2px 2px at 25% 85%, #b06bff55, transparent 60%);
    animation: lobbyParticleFloat 9s ease-in-out infinite;
  }
  @keyframes lobbyGridDrift{0%{background-position:0 0,0 0;} 100%{background-position:34px 34px,34px 34px;}}
  @keyframes lobbyParticleFloat{0%,100%{transform:translateY(0); opacity:.8;} 50%{transform:translateY(-10px); opacity:1;}}
  #mpLobbyScreen .subscreen{position:relative; z-index:1; display:flex; flex-direction:column; min-height:100%;}

  /* Room code panel */
  .room-code-box{
    padding:24px 20px; text-align:center; margin-bottom:14px; position:relative;
    border:1px solid #5ec2ff44; background:linear-gradient(180deg,#0e1a3af5,#0a1330f5);
    box-shadow:0 0 0 1px #5ec2ff1a inset, 0 0 30px #3fa9ff22, 0 10px 30px #00000066;
  }
  .room-code-label{font-size:.72em; color:var(--dim); letter-spacing:3px; margin-bottom:10px; font-weight:800;}
  .room-code-row{display:flex; align-items:center; justify-content:center; gap:14px; flex-wrap:wrap;}
  .room-code-value{font-size:2.3em; font-weight:900; letter-spacing:7px; color:var(--blue-glow); text-shadow:0 0 20px #3fa9ffaa, 0 0 40px #3fa9ff44;}
  .copy-btn{
    padding:8px 14px; border-radius:10px; font-size:.7em; font-weight:800; letter-spacing:1px;
    color:var(--blue-glow); border:1px solid #5ec2ff55; background:#0a1836cc; cursor:pointer; transition:all .2s ease;
  }
  .copy-btn:active{transform:scale(.94);}
  .copy-btn.copied{color:var(--green); border-color:#37e39a77; background:#0d2b22cc;}
  .room-code-hint{margin-top:12px; font-size:.75em; color:var(--dim);}
  .room-players-count{margin-top:10px; font-size:.8em; color:var(--dim); font-weight:700;}

  /* Player-count status panel (5-player minimum) */
  .lobby-status-box{padding:16px; text-align:center; margin-bottom:14px; border:1px solid var(--panel-line); transition:border-color .3s ease;}
  .lobby-status-text{font-size:.82em; font-weight:800; letter-spacing:1.5px; color:var(--dim);}
  .lobby-status-count{margin-top:6px; font-size:1.1em; font-weight:900; color:var(--blue-glow); letter-spacing:1px;}
  .lobby-status-box.ready{border-color:#37e39a55; box-shadow:0 0 20px #37e39a22;}
  .lobby-status-box.ready .lobby-status-text{color:var(--green);}
  .lobby-status-box.ready .lobby-status-count{color:var(--green); text-shadow:0 0 14px #37e39a88;}
  .lobby-progress-track{height:5px; border-radius:4px; background:#0a1836; margin-top:10px; overflow:hidden;}
  .lobby-progress-fill{height:100%; width:0%; background:linear-gradient(90deg,var(--blue),var(--blue-glow)); box-shadow:0 0 10px #3fa9ffaa; transition:width .4s ease, background .3s ease;}
  .lobby-status-box.ready .lobby-progress-fill{background:linear-gradient(90deg,var(--green),#5ef0bd); box-shadow:0 0 12px #37e39aaa;}

  /* Player list */
  .lobby-player-list{flex:1; overflow-y:auto; -webkit-overflow-scrolling:touch; touch-action:pan-y; max-height:38vh; padding-right:2px;}
  .mp-player-row{display:flex; align-items:center; gap:12px; padding:12px 14px; margin-bottom:8px; border:1px solid var(--panel-line); animation:mpRowIn .25s ease;}
  @keyframes mpRowIn{from{opacity:0; transform:translateY(6px);} to{opacity:1; transform:translateY(0);}}
  .mp-player-row.is-ready{border-color:#37e39a55; box-shadow:0 0 14px #37e39a22;}
  .mp-player-row .mp-avatar{width:38px; height:38px; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:1.05em; background:radial-gradient(circle at 35% 30%,#7fd0ff,#1f6fe0 60%,#0b2f6b); flex-shrink:0; box-shadow:0 0 12px #3fa9ff88;}
  .mp-player-row .mp-name{flex:1; font-weight:700; font-size:.92em; display:flex; align-items:center; gap:6px; min-width:0;}
  .mp-player-row .mp-name .nm{overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}
  .mp-player-row .mp-host-tag{font-size:.65em; color:var(--gold); font-weight:800; flex-shrink:0;}
  .mp-player-row .mp-ready-tag{font-size:.72em; font-weight:800; color:var(--dim); padding:5px 11px; border-radius:10px; background:#0a1836; flex-shrink:0; letter-spacing:.3px;}
  .mp-player-row .mp-ready-tag.ready{color:var(--green); background:#0d2b22; box-shadow:0 0 10px #37e39a33;}

  /* Lobby action buttons */
  .lobby-actions{display:flex; gap:10px;}
  .lobby-btn{flex:1;}
  .lobby-start-btn{position:relative; overflow:hidden; transition:opacity .25s ease, box-shadow .25s ease; font-size:.95em;}
  .lobby-start-btn.locked{opacity:.42; pointer-events:none; background:linear-gradient(180deg,#182a5c,#0f1c40); box-shadow:none; border-color:#ffffff1a; font-size:.72em; letter-spacing:.3px;}
  .lobby-start-btn.unlocked{animation:startBtnPulse 1.8s ease-in-out infinite;}
  @keyframes startBtnPulse{0%,100%{box-shadow:0 0 18px #3fa9ff66, inset 0 1px 0 #ffffff33;} 50%{box-shadow:0 0 34px #3fa9ffcc, inset 0 1px 0 #ffffff33;}}


  /* ---------- Local profile avatar ---------- */
  .avatar-img{width:100%; height:100%; border-radius:50%; object-fit:cover; display:block;}
  .avatar{cursor:pointer;}
  .avatar .avatar-edit-badge{
    position:absolute; right:-2px; bottom:-2px; width:20px; height:20px; border-radius:50%;
    background:#0a1836; border:2px solid var(--bg-navy); display:flex; align-items:center; justify-content:center;
    font-size:.6em; box-shadow:0 0 8px #3fa9ffaa;
  }
  .hud-avatar-img{width:100%; height:100%; border-radius:50%; object-fit:cover; display:block;}
  .mp-player-row .mp-avatar{overflow:hidden;}
  .mp-player-row .mp-avatar img{width:100%; height:100%; border-radius:50%; object-fit:cover; display:block;}

  .hud-player-pill{display:flex; align-items:center; gap:7px; padding:6px 12px 6px 6px;}
  .hud-player-pill .hud-avatar-wrap{
    width:24px; height:24px; border-radius:50%; flex-shrink:0; overflow:hidden;
    background:radial-gradient(circle at 35% 30%, #7fd0ff, #1f6fe0 60%, #0b2f6b); box-shadow:0 0 8px #3fa9ff88;
  }
  .hud-player-pill .hud-player-name{font-size:.85em; font-weight:800; max-width:110px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;}

  /* ---------- Profile modal (name + local photo) ---------- */
  .profile-modal{max-width:320px;}
  .avatar-picker{position:relative; width:88px; height:88px; margin:0 auto 14px; cursor:pointer;}
  .avatar-picker-circle{
    width:88px; height:88px; border-radius:50%; overflow:hidden;
    background:radial-gradient(circle at 35% 30%, #7fd0ff, #1f6fe0 60%, #0b2f6b);
    box-shadow:0 0 26px #3fa9ffaa, inset -4px -4px 10px #00174066; border:2px solid #5ec2ff55;
  }
  .avatar-picker-circle img{width:100%; height:100%; border-radius:50%; object-fit:cover; display:block;}
  .avatar-picker-edit{
    position:absolute; right:-2px; bottom:-2px; width:30px; height:30px; border-radius:50%;
    background:linear-gradient(135deg,var(--blue),#1f6fe0); border:2px solid var(--bg-navy);
    display:flex; align-items:center; justify-content:center; font-size:.85em; box-shadow:0 0 12px #3fa9ffaa;
  }

  /* ---------- Multiplayer entry: Quick Match / Private Room ---------- */
  .mp-entry-options{display:flex; flex-direction:column; gap:14px; margin-top:6px;}
  .mp-quick-btn{
    position:relative; overflow:hidden; padding:22px 20px; flex-direction:column; gap:6px;
    background:linear-gradient(135deg, var(--blue), #1f6fe0 55%, #0b3f8f);
    box-shadow:0 0 30px #3fa9ff55, inset 0 1px 0 #ffffff33; border-color:#5ec2ff77;
  }
  .mp-quick-btn::before{
    content:''; position:absolute; inset:-45%; background:radial-gradient(circle, #ffffff2a, transparent 62%);
    animation:mpGlowPulse 2.6s ease-in-out infinite; pointer-events:none;
  }
  .mp-quick-btn .mp-opt-title{position:relative; z-index:1; font-size:1.15em; font-weight:900; letter-spacing:.5px;}
  .mp-quick-btn .mp-opt-sub{position:relative; z-index:1; font-size:.72em; font-weight:600; opacity:.85; letter-spacing:.3px;}
  .mp-private-btn{padding:18px 20px; flex-direction:column; gap:4px;}
  .mp-private-btn .mp-opt-title{font-size:1em; font-weight:800;}
  .mp-private-btn .mp-opt-sub{font-size:.7em; color:var(--dim); font-weight:600;}

  /* ---------- Quick Match matchmaking screen ---------- */
  .qm-panel{padding:36px 24px; text-align:center; margin:auto 0;}
  .qm-radar{
    width:120px; height:120px; margin:0 auto 22px; border-radius:50%; position:relative;
    border:2px solid #5ec2ff33; display:flex; align-items:center; justify-content:center;
  }
  .qm-radar::before, .qm-radar::after{
    content:''; position:absolute; inset:0; border-radius:50%; border:2px solid #5ec2ff55;
    animation:qmRadarPulse 2.2s ease-out infinite;
  }
  .qm-radar::after{animation-delay:1.1s;}
  @keyframes qmRadarPulse{0%{transform:scale(.55); opacity:1;} 100%{transform:scale(1.35); opacity:0;}}
  .qm-radar-core{width:54px; height:54px; border-radius:50%; background:radial-gradient(circle at 35% 30%, #7fd0ff, #1f6fe0 60%, #0b2f6b); box-shadow:0 0 30px #3fa9ffaa; z-index:1;}
  .qm-status-text{font-weight:900; letter-spacing:1.5px; font-size:1em; color:var(--blue-glow); margin-bottom:8px;}
  .qm-status-text.found{color:var(--green); text-shadow:0 0 16px #37e39a88;}
  .qm-count-text{font-size:1.4em; font-weight:900; color:var(--text); margin-bottom:22px;}
  .qm-count-text .req{color:var(--dim); font-weight:700; font-size:.6em;}

  #mpJoinInput{letter-spacing:6px; text-transform:uppercase; font-weight:900;}

  /* ---------- Locked / account screens ---------- */
  .lock-panel{padding:34px 24px; text-align:center; margin:auto 0;}
  .lock-emoji{font-size:3em; margin-bottom:10px;}
  .lock-title{font-weight:900; font-size:1.15em; letter-spacing:.5px; color:var(--red-glow); margin-bottom:10px;}
  .lock-desc{color:var(--dim); font-size:.92em; line-height:1.5; margin-bottom:18px;}
  .lock-progress{font-weight:800; color:var(--gold); font-size:.95em; margin-bottom:22px;}
  .auth-panel{padding:26px 22px; margin:auto 0;}
  .auth-tabs{display:flex; gap:8px; margin-bottom:18px; background:#0a1836; border-radius:14px; padding:4px;}
  .auth-tab{flex:1; text-align:center; padding:10px; border-radius:11px; font-weight:800; font-size:.85em; color:var(--dim); cursor:pointer;}
  .auth-tab.active{background:linear-gradient(135deg,var(--blue),#1f6fe0); color:#fff; box-shadow:0 4px 14px #3fa9ff44;}
  .auth-field{margin-bottom:12px; text-align:left;}
  .auth-field label{display:block; font-size:.72em; color:var(--dim); letter-spacing:1px; margin-bottom:6px; text-transform:uppercase;}
  .auth-field input{
    width:100%; padding:13px 14px; border-radius:12px; border:1px solid var(--panel-line);
    background:#0a1836; color:var(--text); font-size:.95em; outline:none;
  }
  .auth-field input:focus{border-color:var(--blue);}
  .auth-error{color:var(--red-glow); font-size:.82em; font-weight:700; text-align:center; min-height:1.2em; margin:6px 0 4px;}
  .auth-account-row{display:flex; align-items:center; gap:10px; padding:12px 14px; margin-bottom:14px;}
  .auth-account-row .who{flex:1; font-size:.85em; color:var(--dim);}
  .auth-account-row .who b{color:var(--text);}

  /* ---------- Multiplayer button (neon sci-fi network icon) ---------- */
  .btn-multiplayer{
    position:relative; overflow:hidden;
    background:linear-gradient(135deg, #0b1e46, #142a5c 55%, #0a1836);
    border:1px solid #3fa9ff66;
    box-shadow:0 0 0 1px #3fa9ff1f inset, 0 6px 20px #3fa9ff26;
  }
  .btn-multiplayer::before{
    content:''; position:absolute; inset:-45%;
    background:radial-gradient(circle, #3fa9ff3a, transparent 62%);
    animation:mpGlowPulse 2.6s ease-in-out infinite;
    pointer-events:none;
  }
  @keyframes mpGlowPulse{
    0%,100%{ opacity:.45; transform:scale(.88); }
    50%{ opacity:1; transform:scale(1.1); }
  }
  .btn-multiplayer .mp-icon-wrap{
    position:relative; z-index:1; display:flex; align-items:center; justify-content:center;
    filter:drop-shadow(0 0 6px #5ec2ffcc);
  }
  .btn-multiplayer .mp-node{ fill:#8fd4ff; }
  .btn-multiplayer .mp-node.n1{ fill:#5ec2ff; }
  .btn-multiplayer .mp-link{ stroke:#5ec2ffb0; stroke-width:2; }
  .btn-multiplayer .mp-label{ position:relative; z-index:1; letter-spacing:1px; text-shadow:0 0 10px #3fa9ff88; }
  .btn-multiplayer:active{ transform:scale(.96); box-shadow:0 2px 10px #3fa9ff44; }
  .btn-multiplayer:active::before{ animation-play-state:paused; opacity:.8; }

  /* ============================== BOOT / LOADING SCREEN ============================== */
  #bootScreen{
    position:fixed; inset:0; z-index:9999;
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    background:
      radial-gradient(900px 600px at 50% 30%, #10214f66, transparent 65%),
      radial-gradient(700px 500px at 50% 85%, #3fa9ff14, transparent 70%),
      linear-gradient(180deg, #060b1c 0%, #030509 100%);
    overflow:hidden; touch-action:none;
    transition:opacity .55s ease, visibility .55s ease;
  }
  #bootScreen.hidden{ opacity:0; visibility:hidden; pointer-events:none; }

  #bootParticles{ position:absolute; inset:0; width:100%; height:100%; }

  .boot-core{ position:relative; width:220px; height:220px; display:flex; align-items:center; justify-content:center; margin-bottom:18px; }

  .boot-ring{
    position:absolute; border-radius:50%; border:1.5px solid transparent;
    box-shadow:0 0 18px #3fa9ff33 inset;
  }
  .boot-ring.r1{
    width:210px; height:210px;
    border-top-color:#3fa9ffaa; border-right-color:#3fa9ff22;
    animation:bootSpin 3.6s linear infinite;
  }
  .boot-ring.r2{
    width:170px; height:170px;
    border-bottom-color:#5ec2ffaa; border-left-color:#5ec2ff22;
    animation:bootSpin 2.6s linear infinite reverse;
  }
  .boot-ring.r3{
    width:132px; height:132px;
    border-top-color:#ff4d6a99; border-left-color:#ff4d6a22;
    animation:bootSpin 4.4s linear infinite;
  }
  @keyframes bootSpin{ from{ transform:rotate(0deg); } to{ transform:rotate(360deg); } }

  .boot-orb{
    position:relative; width:96px; height:96px; border-radius:50%;
    background:radial-gradient(circle at 35% 30%, #bfe8ff, #3fa9ff 55%, #0b2f6b 100%);
    box-shadow:0 0 40px #3fa9ffcc, 0 0 90px #3fa9ff55, inset 0 0 24px #ffffff55;
    animation:bootPulse 2.2s ease-in-out infinite;
  }
  .boot-orb::after{
    content:''; position:absolute; inset:-14px; border-radius:50%;
    background:radial-gradient(circle, #ff4d6a33, transparent 70%);
    animation:bootWobble 2.2s ease-in-out infinite reverse;
  }
  @keyframes bootPulse{
    0%,100%{ transform:scale(1); box-shadow:0 0 40px #3fa9ffcc, 0 0 90px #3fa9ff55, inset 0 0 24px #ffffff55; }
    50%{ transform:scale(1.08); box-shadow:0 0 55px #3fa9ffee, 0 0 120px #3fa9ff77, inset 0 0 30px #ffffff77; }
  }
  @keyframes bootWobble{ 0%,100%{ transform:scale(.9); opacity:.7; } 50%{ transform:scale(1.15); opacity:1; } }

  .boot-title{
    font-weight:900; letter-spacing:5px; font-size:2.5em; text-align:center; margin:6px 0 2px;
    background:linear-gradient(90deg, var(--blue-glow), #fff 45%, var(--red-glow));
    -webkit-background-clip:text; background-clip:text; color:transparent;
    text-shadow:0 0 30px #3fa9ff77;
    animation:bootTitleGlow 2.4s ease-in-out infinite;
  }
  @keyframes bootTitleGlow{
    0%,100%{ filter:drop-shadow(0 0 8px #3fa9ff66); }
    50%{ filter:drop-shadow(0 0 20px #5ec2ffbb); }
  }
  .boot-tagline{
    color:var(--dim); font-size:.72em; letter-spacing:4px; text-align:center; margin-bottom:28px;
  }

  .boot-bar-wrap{
    width:230px; max-width:70vw; height:8px; border-radius:6px;
    background:#0d1938; border:1px solid #1e3a6d; overflow:hidden;
    box-shadow:inset 0 0 8px #000a;
  }
  .boot-bar-fill{
    height:100%; width:0%; border-radius:6px;
    background:linear-gradient(90deg, var(--blue), var(--blue-glow), var(--red-glow));
    box-shadow:0 0 12px #3fa9ffaa;
    transition:width .12s linear;
  }
  .boot-pct{
    margin-top:10px; font-size:.8em; font-weight:800; letter-spacing:1px; color:var(--blue-glow);
    text-shadow:0 0 10px #3fa9ff66;
  }
  .boot-status{
    margin-top:14px; font-size:.7em; font-weight:700; letter-spacing:2.5px; color:var(--dim);
    text-align:center; min-height:1.4em;
  }
  .boot-status.ready{ color:var(--green); text-shadow:0 0 12px #37e39a88; }

  /* ============================== ADMOB BANNER AD (infrastructure only) ==============================
     Reserved slot for a real native AdMob banner view. This container is purely a placeholder —
     it never draws a fake ad. It is only toggled visible on non-gameplay screens (see
     updateBannerForScreen() in the main script) and always sits below any gameplay HUD. */
  #admobBannerContainer{
    position:fixed; left:0; right:0; bottom:0;
    display:none;
    z-index:40;
    justify-content:center; align-items:center;
    padding-bottom:env(safe-area-inset-bottom, 0px);
  }
  #admobBannerContainer.visible{ display:flex; }
  #admobBannerSlot{
    width:100%; max-width:100%; min-height:50px;
    display:flex; align-items:center; justify-content:center;
  }
  #admobBannerFallback{
    font-size:.62em; letter-spacing:1px; color:var(--dim); opacity:.5; padding:4px 0;
  }

  /* ---------- Main Menu — premium/futuristic visual polish (visual only) ---------- */
  #menu .brand{ filter:drop-shadow(0 0 18px #3fa9ff44); }
  .profile-card{
    background:linear-gradient(160deg,#101f45cc,#0a1330e6);
    border:1px solid #2a4a8a;
    box-shadow:0 10px 34px #00000070, inset 0 1px 0 #ffffff14, 0 0 22px #3fa9ff14;
  }
  .avatar{ box-shadow:0 0 0 2px #0a1330, 0 0 0 4px #3fa9ff66, 0 0 26px #3fa9ffaa, inset -4px -4px 10px #00174066; }
  .profile-name{ letter-spacing:.3px; }
  .menu-buttons .btn.primary{
    position:relative; overflow:hidden;
    box-shadow:0 10px 28px #3fa9ff4a, inset 0 1px 0 #ffffff3d;
    letter-spacing:1px;
  }
  .menu-buttons .btn.primary::after{
    content:''; position:absolute; top:0; left:-60%; width:40%; height:100%;
    background:linear-gradient(120deg, transparent, #ffffff35, transparent);
    transform:skewX(-20deg); pointer-events:none;
    animation:menuShine 3.6s ease-in-out infinite;
  }
  @keyframes menuShine{0%{left:-60%;} 45%,100%{left:130%;}}
  .menu-row .btn.glass{ border-color:#28407a; }
  .menu-row .btn.glass span.big{ filter:drop-shadow(0 0 5px #3fa9ff44); }
  .challenges{
    border:1px solid #22335f;
    background:linear-gradient(180deg,#0e1a3ae6,#0a1330cc);
    box-shadow:0 8px 26px #00000055, inset 0 1px 0 #ffffff0f;
  }
  .challenges h3{ color:var(--blue-glow); font-weight:800; }

  /* ---------- Friend Chat — cleaner, more futuristic finish (visual only) ---------- */
  /* Chat incoming bubbles — premium indigo/violet instead of red. */
  .chat-bubble.them{
    background:linear-gradient(160deg,#3b315f,#211b3d);
    border-color:#9a7dff55;
    box-shadow:0 4px 16px #00000040, inset 0 1px 0 #ffffff12;
  }

  .chat-header{ background:linear-gradient(180deg,#0b1430f0,#060a18f5); border-bottom:1px solid #22335f; }
  .chat-header-name{
    background:linear-gradient(90deg,var(--blue-glow),#eaf2ff);
    -webkit-background-clip:text; background-clip:text; color:transparent;
  }
  .chat-body{ background:radial-gradient(900px 480px at 50% -8%, #10254d24, transparent 62%); }
  .chat-bubble{ border-radius:18px; backdrop-filter:blur(6px); box-shadow:0 4px 16px #00000040, inset 0 1px 0 #ffffff12; }
  .chat-bubble.me{ background:linear-gradient(160deg,#1e3f80,#122457); border:1px solid #5ec2ff5c; border-bottom-right-radius:6px; }
  .chat-bubble.them{ background:linear-gradient(160deg,#7e2c20,#3f130f); border:1px solid #ff7d925c; border-bottom-left-radius:6px; }
  .chat-input-bar{ background:linear-gradient(180deg,#0b1430f0,#060a18f7); border-top:1px solid #22335f; }
  .chat-input-bar input{ border-radius:24px; background:#0c1c40; }

  /* Shared chat send button — supplied ORBEX arrow asset. */
  .chat-send-btn{
    width:44px; height:44px; padding:0 !important; border-radius:50%;
    flex-shrink:0; display:flex; align-items:center; justify-content:center; overflow:hidden;
    background:linear-gradient(135deg,var(--blue),#1f6fe0);
    border:1px solid #8ddcff66;
    box-shadow:0 6px 18px #3fa9ff55,inset 0 1px 0 #ffffff33;
    transition:transform .1s ease,opacity .15s ease,filter .15s ease,box-shadow .15s ease;
  }
  .chat-send-btn:active{transform:scale(.92);}
  .chat-send-btn.is-disabled,.chat-send-btn[aria-disabled="true"]{
    opacity:.42; filter:saturate(.7); pointer-events:none;
    box-shadow:0 3px 10px #00000030,inset 0 1px 0 #ffffff18;
    background:linear-gradient(135deg,#6fb9e8,#3979b8);
  }
  .chat-send-arrow-img{
    width:24px; height:29px; display:block; flex:0 0 24px; pointer-events:none;
    background-image:url("data:image/png;base64,"); background-repeat:no-repeat; background-position:center; background-size:contain;
    filter:drop-shadow(0 0 5px #5ec2ff99); transform:translate(1px,0);
  }
  .chat-send-btn.is-disabled .chat-send-arrow-img{filter:drop-shadow(0 0 3px #7ec8f866);}
  .chat-input-row .chat-send-btn{margin:0; padding:0 !important;}

  /* Long-press-to-delete popover for individual chat messages (own messages only) */
  .msg-delete-popover{
    position:absolute; z-index:65; display:none;
    background:linear-gradient(180deg,#101f45,#0a1330);
    border:1px solid #ff4d6a55; border-radius:12px;
    box-shadow:0 10px 26px #000000aa, inset 0 1px 0 #ffffff14;
    padding:4px;
  }
  .msg-delete-popover.show{ display:block; animation:msgDeletePop .12s ease-out; }
  @keyframes msgDeletePop{ 0%{opacity:0;transform:translateY(4px) scale(.88);} 70%{opacity:1;transform:translateY(-1px) scale(1.02);} 100%{opacity:1;transform:translateY(0) scale(1);} }
  .msg-delete-btn{
    display:flex; align-items:center; gap:8px; padding:10px 16px;
    color:var(--red); font-weight:800; font-size:.85em; white-space:nowrap;
    border-radius:9px; cursor:pointer;
  }
  .msg-delete-btn:active{ background:#ff4d6a22; }
  .msg-delete-icon{ font-size:1em; }

/* Gameplay feedback polish: combo presentation only. */
.combo-text{
  --combo-scale:.7;
  transform:translateX(0) scale(.72);
  filter:drop-shadow(0 0 10px rgba(255,206,84,.35));
  transition:opacity .14s ease, transform .16s cubic-bezier(.2,1.35,.35,1), filter .16s ease;
}
.combo-text.show{
  opacity:1;
  transform:translateX(0) scale(var(--combo-scale));
  filter:drop-shadow(0 0 18px rgba(255,206,84,.58));
}

/* ---------- ORBEX lobby theme backdrops (additive; existing lobby UI remains unchanged) ---------- */
#mpLobbyScreen{background:#050914;}
#lobbyThemeBackdrop{
  position:absolute;
  inset:0;
  z-index:0;
  pointer-events:none;
  background-color:#050914;
  background-repeat:no-repeat;
  background-position:center center;
  background-size:contain;
  opacity:.82;
}
#lobbyThemeBackdrop::after{
  content:'';
  position:absolute;
  inset:0;
  background:
    linear-gradient(180deg,#05091470 0%,#05091435 42%,#05091478 100%),
    radial-gradient(circle at 50% 42%,transparent 0%,#05091455 72%,#050914b8 100%);
