  #lobbyThemeBackdrop{
    background-size:auto 100%;
    opacity:.76;
  }
  #lobbyThemeBackdrop::after{
    background:
      linear-gradient(90deg,#050914 0%,#05091410 20%,#05091410 80%,#050914 100%),
