  }
}

/* ---------- Lightweight shared emoji picker for existing multiplayer/DM chat ---------- */
.chat-emoji-trigger{
  width:42px;
  height:42px;
  flex:0 0 42px;
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  border:1px solid #5ec2ff44;
  background:#0a1836;
  color:#bfe8ff;
  font-size:1.35em;
  line-height:1;
  cursor:pointer;
  user-select:none;
  -webkit-tap-highlight-color:transparent;
  box-shadow:0 0 10px #3fa9ff1c,inset 0 1px 0 #ffffff10;
  transition:transform .1s ease,box-shadow .15s ease,border-color .15s ease;
}
.chat-emoji-trigger:active{transform:scale(.92);}
.chat-emoji-trigger:focus-visible{outline:2px solid #5ec2ff88;outline-offset:2px;}
.chat-emoji-picker{
  position:fixed;
  z-index:1000;
  display:none;
  width:min(310px,calc(100vw - 24px));
  max-height:min(260px,45vh);
  overflow-y:auto;
  padding:9px;
  border:1px solid #5ec2ff44;
  border-radius:16px;
  background:linear-gradient(180deg,#101f45f7,#07112bf7);
  box-shadow:0 14px 40px #00000088,inset 0 1px 0 #ffffff12;
  backdrop-filter:blur(14px);
  -webkit-backdrop-filter:blur(14px);
}
.chat-emoji-picker.show{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;}
.chat-emoji-item{
  min-width:0;
  aspect-ratio:1;
  border:0;
  border-radius:10px;
  background:transparent;
  color:#fff;
  font-size:1.35rem;
  cursor:pointer;
  display:flex;
  align-items:center;
  justify-content:center;
  -webkit-tap-highlight-color:transparent;
}
.chat-emoji-item:active{background:#5ec2ff22;transform:scale(.92);}
@media (max-width:420px){
  .chat-emoji-picker.show{grid-template-columns:repeat(6,1fr);}
  .chat-emoji-trigger{width:40px;height:40px;flex-basis:40px;}
}

/* Bounty presentation polish only; bounty gameplay/reward logic is untouched. */
.bounty-pill{
  border-color:#ff4d6a77;
  text-shadow:0 0 10px #ff4d6a66;
  box-shadow:0 0 10px #ff4d6a22;
}

/* ---------- Local mode map selection (additive) ---------- */
#localMapScreen{background:#050914;}
.local-map-subscreen{max-width:760px;}
.local-map-kicker{text-align:center;color:var(--dim);font-size:.78em;letter-spacing:2.5px;font-weight:800;margin:4px 0 16px;}
.local-map-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;}
.local-map-card{overflow:hidden;padding:0;cursor:pointer;border:1px solid #ffffff12;transition:transform .16s ease,border-color .16s ease,box-shadow .16s ease;}
.local-map-card:active{transform:scale(.985);}
.local-map-card.selected{border-color:#5ec2ffcc;box-shadow:0 0 0 1px #5ec2ff55,0 0 24px #3fa9ff22;}
.local-map-image{height:190px;overflow:hidden;background:#07102a;}
.local-map-image img{display:block;width:100%;height:100%;object-fit:cover;object-position:center;}
.local-map-card-label{padding:12px 10px;text-align:center;font-size:.82em;font-weight:900;letter-spacing:1px;color:#eaf2ff;}
.local-map-card.selected .local-map-card-label{color:#8fd4ff;text-shadow:0 0 10px #3fa9ff55;}
.local-map-selection-hint{text-align:center;color:var(--dim);font-size:.78em;margin:14px 0 10px;min-height:18px;}
.local-map-start{width:100%;}
.local-map-start.locked{opacity:.5;pointer-events:none;}
#gameCanvas{background-repeat:no-repeat;background-position:center center;background-size:cover;background-color:#050914;}
@media (max-width:600px){
  .local-map-grid{grid-template-columns:1fr 1fr;gap:9px;}
  .local-map-image{height:145px;}
  .local-map-card-label{padding:10px 6px;font-size:.72em;letter-spacing:.7px;}
}
@media (min-width:900px){
  .local-map-image{height:220px;}
  #gameCanvas{background-size:auto 100%;}
}

/* Map UI repair: keep the existing four card images rendered. */
.local-map-image img{visibility:visible!important;opacity:1!important;display:block!important;}

/* Spectator Mode indicator (added — does not affect existing HUD/gameplay styles) */
.spectator-indicator{
  position:absolute;
  top:64px;
  left:50%;
  transform:translateX(-50%) translateY(-8px);
  padding:8px 16px;
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:2px;
  z-index:40;
  opacity:0;
  pointer-events:none;
  transition:opacity .25s ease, transform .25s ease;
}
.spectator-indicator.show{
  opacity:1;
  transform:translateX(-50%) translateY(0);
}
.spectator-label{
  font-weight:900;
  letter-spacing:1.5px;
  font-size:.85em;
  color:#ffce54;
}
.spectator-watching{
  font-size:.72em;
  color:var(--dim,#8a94a6);
}
.spectator-exit-btn{
  position:absolute;
  top:64px;
  right:14px;
  width:34px;
  height:34px;
  display:none;
  align-items:center;
  justify-content:center;
  z-index:40;
  color:#eaf2ff;
}
.spectator-exit-btn.show{display:flex;}

/* ============================================================
   POLARIX CHAT UI — VISUAL-ONLY PREMIUM FUTURISTIC SKIN
   No chat structure, IDs, JS behavior, Firebase, or layout logic changed.
   ============================================================ */

/* Shared futuristic chat surface */
.chat-screen .chat-header,
.chat-screen .chat-input-bar,
.chat-panel {
  border-color: #6bdfff38;
  background: linear-gradient(180deg, rgba(9,20,31,.94), rgba(4,12,21,.92));
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow: 0 0 24px rgba(70,210,255,.07), inset 0 1px 0 rgba(255,255,255,.08);
}

/* Dedicated DM header */
.chat-screen .chat-header {
  gap: 14px;
  border-bottom: 1px solid rgba(113,225,255,.28);
  box-shadow: 0 6px 24px rgba(0,0,0,.28), inset 0 1px 0 rgba(255,255,255,.09);
}

.chat-screen .chat-header .icon-btn {
  border: 1px solid rgba(142,224,255,.34);
  background: linear-gradient(145deg, rgba(55,90,108,.48), rgba(8,22,34,.76));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.10), 0 4px 16px rgba(0,0,0,.24);
  color: #d9f5ff;
}

.chat-screen .chat-header .back-btn {
  color: #ccefff;
}

.chat-screen .chat-header-name {
  color: #9deeff;
  text-shadow: 0 0 12px rgba(91,221,255,.22);
  letter-spacing: .35px;
}

.chat-screen .chat-header-status {
  color: #9aaab5;
}

.chat-screen .chat-header-status.online {
  color: #9fdbe8;
}

.chat-screen .chat-header-status .status-dot.online {
  background: #7cecff;
  box-shadow: 0 0 8px rgba(82,226,255,.62);
}

/* Subtle sci-fi grid behind messages — visual only */
.chat-screen .chat-body {
  position: relative;
  background-color: #07131e;
  background-image:
    linear-gradient(rgba(104,213,244,.075) 1px, transparent 1px),
    linear-gradient(90deg, rgba(104,213,244,.075) 1px, transparent 1px),
    radial-gradient(700px 460px at 50% 0%, rgba(57,191,235,.13), transparent 68%);
  background-size: 48px 48px, 48px 48px, auto;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.03);
}

/* Premium message bubbles */
.chat-screen .chat-bubble {
  border-radius: 18px;
  padding: 10px 13px 7px;
  color: #e4e9ed;
  font-size: .86em;
  line-height: 1.38;
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  box-shadow: 0 5px 18px rgba(0,0,0,.28), inset 0 1px 0 rgba(255,255,255,.10);
}

.chat-screen .chat-bubble.me {
  background: linear-gradient(145deg, rgba(53,103,119,.68), rgba(18,38,50,.84));
  border: 1px solid rgba(116,229,255,.52);
  border-bottom-right-radius: 6px;
  box-shadow: 0 5px 20px rgba(0,0,0,.28), 0 0 14px rgba(78,218,255,.08), inset 0 1px 0 rgba(215,249,255,.12);
}

.chat-screen .chat-bubble.them {
  background: linear-gradient(145deg, rgba(117,125,132,.62), rgba(50,57,64,.76));
  border: 1px solid rgba(205,221,230,.40);
  border-bottom-left-radius: 6px;
  box-shadow: 0 5px 18px rgba(0,0,0,.30), inset 0 1px 0 rgba(255,255,255,.14);
}

.chat-screen .chat-bubble-time {
  color: #82919b;
  font-size: .66em;
}

.chat-screen .chat-msg-tick {
  color: #8799a4;
}

.chat-screen .chat-msg-tick.read {
  color: #7cecff;
  text-shadow: 0 0 6px rgba(124,236,255,.25);
}

/* Reply quote / pending reply */
.chat-screen .chat-reply-quote {
  border-left-color: rgba(133,231,255,.70);
  background: rgba(0,0,0,.18);
}

.chat-screen .chat-reply-preview {
  border-top-color: rgba(107,223,255,.22);
  background: rgba(7,20,31,.93);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.chat-screen .chat-reply-preview-bar {
  background: #7cecff;
  box-shadow: 0 0 8px rgba(124,236,255,.25);
}

.chat-screen .chat-reply-preview-name {
  color: #91eaff;
}

/* Input bar: glass + cyan edge */
.chat-screen .chat-input-bar {
  border-top: 1px solid rgba(112,225,255,.25);
  background: linear-gradient(180deg, rgba(6,18,28,.91), rgba(3,11,19,.97));
  box-shadow: 0 -7px 22px rgba(0,0,0,.25), inset 0 1px 0 rgba(255,255,255,.06);
}

.chat-screen .chat-input-bar input {
  border: 1px solid rgba(108,224,255,.72);
  background: linear-gradient(180deg, rgba(11,27,39,.78), rgba(5,16,26,.88));
  color: #e5edf1;
  box-shadow: 0 0 12px rgba(80,216,255,.10), inset 0 1px 0 rgba(255,255,255,.07);
}

.chat-screen .chat-input-bar input::placeholder {
  color: #8997a2;
}

.chat-screen .chat-input-bar input:focus {
  border-color: rgba(122,235,255,.96);
  box-shadow: 0 0 0 3px rgba(94,194,255,.10), 0 0 16px rgba(70,215,255,.12);
}

/* Circular emoji control */
.chat-screen .chat-emoji-trigger,
.chat-panel .chat-emoji-trigger {
  border: 1px solid rgba(157,190,207,.30);
  background: radial-gradient(circle at 35% 30%, rgba(85,116,133,.42), rgba(7,18,29,.88));
  color: #c9dce4;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.10), 0 4px 15px rgba(0,0,0,.22);
}

/* Futuristic circular send control */
.chat-screen .chat-send-btn,
.chat-panel .chat-send-btn {
  width: 48px;
  min-width: 48px;
  height: 48px;
  padding: 0 !important;
  border-radius: 50%;
  border: 1px solid rgba(143,226,255,.38);
  background: radial-gradient(circle at 35% 28%, rgba(80,119,138,.54), rgba(8,25,37,.92));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.11), 0 5px 16px rgba(0,0,0,.26), 0 0 12px rgba(77,217,255,.08);
}

.chat-screen .chat-send-btn:active,
.chat-panel .chat-send-btn:active {
  transform: scale(.94);
}

.chat-screen .chat-send-arrow-img,
.chat-panel .chat-send-arrow-img {
  width: 27px;
  height: 27px;
  filter: drop-shadow(0 0 6px rgba(102,226,255,.42));
}

/* Lobby / compact chat uses the same premium language without changing its dimensions */
.chat-panel {
  border: 1px solid rgba(107,223,255,.18);
  border-radius: 16px;
}

.chat-panel .chat-list {
  background:
    linear-gradient(rgba(104,213,244,.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(104,213,244,.045) 1px, transparent 1px);
  background-size: 42px 42px;
  border-radius: 12px;
}

.chat-panel .chat-msg {
  border-color: rgba(167,209,224,.20);
  border-radius: 14px;
  background: linear-gradient(145deg, rgba(75,91,101,.52), rgba(20,31,40,.76));
  box-shadow: 0 4px 14px rgba(0,0,0,.20), inset 0 1px 0 rgba(255,255,255,.08);
}

.chat-panel .chat-msg.me {
  background: linear-gradient(145deg, rgba(48,96,113,.65), rgba(16,38,51,.82));
  border-color: rgba(111,226,255,.40);
}

.chat-panel .chat-msg-name {
  color: #8fe9ff;
  text-shadow: 0 0 8px rgba(91,221,255,.18);
}

.chat-panel .chat-msg-time {
  color: #7f919c;
}

.chat-panel .chat-input-row input {
  border-color: rgba(108,224,255,.45);
  background: rgba(7,21,31,.82);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.06);
}

.chat-panel .chat-input-row input:focus {
  border-color: rgba(122,235,255,.90);
  box-shadow: 0 0 0 3px rgba(94,194,255,.09), 0 0 14px rgba(70,215,255,.10);
}

/* Chat menu — glass sci-fi treatment */
.chat-screen .chat-menu-dropdown {
  background: linear-gradient(180deg, rgba(15,32,43,.96), rgba(5,16,25,.97));
  border-color: rgba(107,223,255,.28);
  box-shadow: 0 12px 30px rgba(0,0,0,.52), 0 0 18px rgba(72,210,255,.07), inset 0 1px 0 rgba(255,255,255,.08);
}

.chat-screen .chat-menu-item:active {
  background: rgba(112,225,255,.10);
}

/* Keep the chat notification visually consistent with the new chat skin */
.chat-notify-banner {
  background: linear-gradient(145deg, rgba(17,37,49,.95), rgba(5,17,27,.97));
  border-color: rgba(107,223,255,.30);
  box-shadow: 0 10px 28px rgba(0,0,0,.38), 0 0 18px rgba(76,215,255,.08), inset 0 1px 0 rgba(255,255,255,.08);
}

.chat-notify-name {
  color: #91eaff;
}



/* ---------- Premium account login ---------- */
#loginScreen{
  background:linear-gradient(180deg,#fbfcff 0%,#f3f6fb 100%);
  color:#111827;
  z-index:100;
}
.login-shell{
  width:min(100%,520px); min-height:100%; margin:auto; padding:34px 20px 22px;
  display:flex; flex-direction:column; justify-content:center; align-items:center;
}
.login-brand{
  font-size:1.55rem; font-weight:900; letter-spacing:.18em; color:#111827;
  margin-bottom:7px;
}
.login-card{
  width:100%; background:rgba(255,255,255,.96); border:1px solid #e4e8ef;
  border-radius:24px; padding:30px 24px 24px; box-shadow:0 20px 60px rgba(15,23,42,.10);
}
.login-kicker{
  font-size:.72rem; font-weight:800; letter-spacing:.16em; color:#64748b; text-align:center;
}
.login-card h1{margin:8px 0 8px; text-align:center; font-size:2rem; line-height:1.1; color:#0f172a;}
.login-subtitle{margin:0 auto 24px; max-width:390px; text-align:center; color:#64748b; line-height:1.5; font-size:.92rem;}
.login-actions{display:flex; flex-direction:column; gap:12px;}
.login-google-btn,.login-guest-btn{
  width:100%; min-height:52px; border-radius:14px; font:inherit; font-weight:800;
  cursor:pointer; display:flex; align-items:center; justify-content:center; gap:11px;
  transition:transform .08s ease,box-shadow .15s ease,opacity .15s ease;
}
.login-google-btn:active,.login-guest-btn:active{transform:scale(.985);}
.login-google-btn{background:#111827;color:#fff;border:1px solid #111827;box-shadow:0 8px 20px rgba(15,23,42,.14);}
.login-guest-btn{background:#fff;color:#1f2937;border:1px solid #d8dee8;}
.login-google-btn.is-loading,.login-guest-btn.is-loading{opacity:.6;pointer-events:none;}
.google-mark{width:23px;height:23px;border-radius:50%;background:#fff;color:#4285f4;display:inline-flex;align-items:center;justify-content:center;font-weight:900;font-family:Arial,sans-serif;}
.login-divider{display:flex;align-items:center;gap:10px;color:#94a3b8;font-size:.7rem;font-weight:800;letter-spacing:.14em;}
.login-divider:before,.login-divider:after{content:"";height:1px;background:#e5e7eb;flex:1;}
.login-status{min-height:20px;margin-top:13px;text-align:center;color:#64748b;font-size:.8rem;font-weight:700;}
.login-status.error{color:#dc2626;}
.login-secure{
  margin-top:18px;padding:12px 13px;border-radius:12px;background:#f8fafc;border:1px solid #edf0f5;
  color:#64748b;font-size:.72rem;line-height:1.45;display:flex;gap:9px;align-items:flex-start;
}
.login-secure-icon{flex:0 0 auto;width:18px;height:18px;border-radius:50%;background:#e8f7ee;color:#15803d;display:inline-flex;align-items:center;justify-content:center;font-weight:900;}
.login-footer{margin-top:18px;font-size:.62rem;letter-spacing:.16em;color:#94a3b8;font-weight:800;}
@media(max-width:420px){
  .login-shell{padding:22px 14px 16px;}
  .login-card{padding:25px 18px 20px;border-radius:20px;}
  .login-card h1{font-size:1.75rem;}
}
